WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.forever = WordHunterWoW_QuestDataByFlavor.forever or {}
WordHunterWoW_QuestDataByFlavor.forever.enUS = WordHunterWoW_QuestDataByFlavor.forever.enUS or {}
WordHunterWoW_QuestEN = WordHunterWoW_QuestDataByFlavor.forever.enUS
WordHunterWoW_QuestEN[96873] = { title = "A Pain in the Neck", description = "The trolls east of here have lost their will to the witchdoctor, Zalazane. He uses many cruel magics to keep hold of his prisoners' minds, but one of his favorite tricks is to make them wear pendants wrapped in evil binding spells.\n\nPractice your enchanting skills by stripping the magic from these pendants, and bring me the results. And don't accidentally put one around your neck, if you value your freedom!", objectives = "Pa'zula in Sen'jin Village wants you to collect 3 Luminous Residue. Luminous Residue can be obtained by disenchanting Hexed Pendants dropped by trolls in the Echo Isles.", progress = "What do you have for me, {name}?", completion = "Fine work. A shame about the slain trolls, but with the binding spells removed, their spirits can rest." }
WordHunterWoW_QuestEN[96874] = { title = "This Is Spinal Axe", description = "Have you seen the huge beasts of Thunder Ridge? I keep thinking the spines on their backs would be perfect for crafting the head of a mighty axe. Saru laughed when I told him... but what does he know!?\n\nAs part of your smithing lessons, you can help me out! Bring me some of those spines, along with grinding stones to sharpen them.", objectives = "Ug'thok in Orgrimmar wants you to collect 5 Weathered Spines from beasts in Thunder Ridge, along with 5 Rough Grinding Stones.", progress = "Yes?", completion = "These spines are tougher than I expected, {name}! Crafting with them may not be as easy as I thought... but I'll keep working on it!" }
WordHunterWoW_QuestEN[96875] = { title = "Beasts of Thunder Ridge", description = "Orgrimmar is always expanding, {class}. And when the peons need hides to line the walls and roofs of our new buildings, they come to me!\n\nThe hides of the lizards in Thunder Ridge are typically too thick for armor, but they make excellent building material. Bring me some of their hides, along with a few lighter cured hides. Let's see your skill with leather!", objectives = "Kamari in Orgrimmar wants you to collect 5 Rough Lizard Hide from beasts in Thunder Ridge, along with 2 Cured Light Hides.", progress = "Yes?", completion = "Your work helps Orgrimmar grow. Know that as you walk the city's paths." }
WordHunterWoW_QuestEN[96876] = { title = "Ukor's Lost Pack", description = "The pack has the name \"Ukor\" crudely stitched along the flap.", objectives = "Return the pack to Ukor in southern Durotar.", progress = "Something need doing?", completion = "My pack! When I dropped it to run from that huge spider, I thought I'd never see it again. You really are a hero!" }
WordHunterWoW_QuestEN[96877] = { title = "Halikor's Hoof", description = "The enormous hoof serves as proof of your victory over the mighty lizard.", objectives = "Deliver Halikor's Hoof to Orgrimmar.", progress = "Yes?", completion = "What a trophy, {class}! That must have been some fight!" }
WordHunterWoW_QuestEN[96895] = { title = "The Argent Emissary", description = "Not sure if you heard, but two emissaries of the Argent Dawn just passed through here. I don't mind the Argent Dawn, but I don't like them poking around Tirisfal unsupervised either. They were both Forsaken... but that doesn't make me any less nervous.\n\nOne of them just passed by here, headed southeast. There's a group of scourge cultists snooping around the outskirts of the city in that direction. If those two heard about them, there's no doubt that would have caught their attention.", objectives = "Find the Argent Dawn member near the entrance to the Undercity.", completion = "Stay low and try not to be seen, {class}. These cultists are not to be trifled with." }
WordHunterWoW_QuestEN[96896] = { title = "A Righteous Cause", description = "Danitha and I fought against the scourge in the defense of the Undercity when Naxxramas attacked. We lost many good friends that day, including the hero after which this keep was named--Garek Bandarion.\n\nHe might just have been the first Forsaken to rediscover how to wield the light as a paladin. I am encouraged to see his legacy and potential live on here with Danitha and her cohort.\n\nIf only the rest of the forsaken felt the same way...", objectives = "Observe the conversation between Danitha Morr and Leonid Barthalomew the Revered.", completion = "I plan to stay here for a time and speak with more of my friends, but I will return to Light's Hope Chapel in Eastern Plaguelands soon enough. Should you ever find yourself out that way, please do say hello. We could always use more help from able-bodied adventurers." }
WordHunterWoW_QuestEN[96897] = { title = "The Cult of the Damned", description = "The scourge are a blight on our lands, and their living servants are the worst of them. The people of Tirisfal have enough to deal with between the mindless dead and the Scarlet Crusade. If you wish to do some good, help me put an end to this scum.", objectives = "Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades.", completion = "Thank you for your aid, {class}. If we do not wish to see Lordaeron's history repeat itself, we've got to be vigilant when threats like this spring up." }
WordHunterWoW_QuestEN[96898] = { title = "Remnants of War", description = "It wasn't long ago that the citadel of Naxxramas bore down upon this city, intent on wiping the Forsaken off the map. Both the Forsaken and the Argent Dawn lost much that day to secure the future of the Forsaken.\n\nDuring the battle, the great necrotic focusing crystal hanging beneath Naxxramas was shattered and its fragments were scattered all over this area. I suspect that is what the cultists are here for. Help me recover the fragments and deprive the scourge of them.", objectives = "Gather 12 Necrotic Crystal Fragments in Tirisfal Glades.", progress = "I'd advise you not come into too much physical contact with those crystals. Even shattered and spent, the lingering magic in these necrotic crystals is highly dangerous.", completion = "Thank you. This should slow the efforts of the scourge in this area. I suspect the denizens of Tirisfal will be pulling these crystals out of the ground for years, but removing the most conspicuous of them can only help." }
WordHunterWoW_QuestEN[96899] = { title = "Bandarion Keep", description = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\n\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess.", objectives = "Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades.", completion = "This place is full of memories for me. This place was once held by the Argent Dawn. It was here from here that we prepared for many battles and skirmishes against the scourge during their most recent push into Tirisfal Glades.\n\nWhen we withdrew to the Plaguelands I feared it would fall into disrepair. My fear was well-founded, but I am glad that Danitha and her paladins have taken over stewardship of it now.\n\nShe even named the keep after... a mutual friend." }
WordHunterWoW_QuestEN[96984] = { title = "Heart of Disruption", description = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\n\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\n\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe.", objectives = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill." }
WordHunterWoW_QuestEN[96986] = { title = "The Grave Knight", description = "Within the underbelly of the mage city to the north is a traitor to our kind. A necromancer of disturbing talent. He raises an army of undeath right under the Kirin Tor's nose.\n\nI care not for the fate of the mage city, {name}, but this grave knight spits in the face of everything we Forsaken stand for. Put an end to him. Show him no one is beyond the reach of the Dark Lady.", objectives = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill." }
WordHunterWoW_QuestEN[96987] = { title = "Opportunistic Education", description = "Well if it ain't a like-minded entrepreneur. Sneakin' into Dalaran durin' such troublesome times? Tsk tsk.\n\nMy kinda {race}!\n\nWhile our mage friends here are occupied, maybe we could find ourselves some 'misplaced' treasures. They gots whole libraries dedicated to fancy arcane magics. If you could bring me one of their secret tomes, I could sell it for a pretty penny. Split the profits with ya.\n\nHey hey don't look at me like that. You ain't exactly here on a field trip yourself. You want in or what?", objectives = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance." }
WordHunterWoW_QuestEN[96988] = { title = "Source of Power", description = "With the city of Dalaran under siege by their own constructs, this is the perfect opportunity to, let's say, borrow a few samples.\n\nImagine an army of arcane-powered abominations. The Dark Lady would have no choice but to recognize my alchemical prowess. Maybe even grant me head of the Royal Apothecary Society?\n\nGo to the city and find the constructs' cores. They are unlikely to give them willingly, so do what you must.", objectives = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity." }
WordHunterWoW_QuestEN[97003] = { title = "Chol'aruk the Ravener", description = "You there, {class}. I need your aid. There are rumors of a beast that makes its lair deep in a cave at Thorn Hill, northeast of here. The Razormane call it Chol'aruk or \"The Ravener\". It's supposedly five times the size of a normal quilboar with a thirst for blood that can never be sated.\n\nMost don't believe the tales. But I do--because I've fought its like before.\n\nSeek out its lair and slay Chol'aruk. Bring me its head. I warn you though--prepare well and do not go alone.\n\nBlood and thunder, {class}.", objectives = "Bring the head of Chol'aruk to Gur'ak in the Barrens.", progress = "It took the strength of six skilled fighters to defeat one of these creatures, and it still managed to fell four of us before we could put it down.\n\nIf these monstrous beasts were to appear in greater numbers, the damage that the qullboar could inflict upon the land could be catastrophic.", completion = "Impressive, {class}. None will doubt my tales when I return to Orgrimmar with this grim proof of the existence of these abominations. Rest assured this glory is yours however, and I will speak loudly of your deeds.\n\nLok-tar!" }
WordHunterWoW_QuestEN[97005] = { title = "Chol'aruk the Ravener", description = "There's rumors of a monstrous abomination that makes its lair at a cave to the northwest of here, on the plateau known as Thorn Hill. The Razormane call it Chol'aruk or \"The Ravener\" and those that have seen it say its so massive that it can swallow an orc whole.\n\nFew believe such tales, but I do... because I've fought one like it myself. On the honor of those I lost to these things, this beast must die.\n\nGather strong allies and find the lair of Chol'aruk. Kill the abomination and bring me it's head.", objectives = "Bring Chol'aruk's Head to Bainham in the Barrens.", progress = "It took six of us to defeat one of these creatures, and it still managed to kill all but myself and one other before we were able to bring it down.\n\nThis far from alliance lands I should leave it well enough alone. Light knows I'll lose little sleep over a few tauren savages or orcish brutes. However, the honor of my fallen brothers demands action.", completion = "My dead men will rest easier knowing that there is one less of these monsters in the world. You've done well, and are a true and stalwart defender of the alliance. Thank you.\n\nGo with honor, {name}." }
WordHunterWoW_QuestEN[97047] = { title = "The Cook in the Cage", description = "Hey! You! You have to help me! I was just out exploring the jungle when, all of a sudden, I was ambushed by these maniacs! I don't know what they plan to do with me, but I've heard talk of tigers and headshrinkers, and I don't want part in either!\n\nI don't know how, but you have to get me out of here! Please! A key to this cage, a disguise to sneak out, something! Anything!", objectives = "Find a key to Wendel's cage, and a disguise for him to sneak out, within the Kurzen compound." }
WordHunterWoW_QuestEN[97048] = { title = "Returning to Port", description = "Listen, I can't repay you right now, but I'm a cook on Captain Aransas' ship. I'll be sure to put in a good word for you when I get back to Booty Bay. You should speak to the captain when you get the chance. I'm sure she'll be grateful to have me back.", objectives = "Speak to Captain Aransas in Booty Bay." }
WordHunterWoW_QuestEN[97065] = { title = "Tip the Scales - Keefer's Angelfish", description = "An angelfish for some tastyfish. Feels like a fair trade to me.", objectives = "" }
WordHunterWoW_QuestEN[97066] = { title = "Tip the Scales - Brownell's Blue Striped Racer", description = "", objectives = "" }
WordHunterWoW_QuestEN[97067] = { title = "Tip the Scales - Dezian Queenfish", description = "", objectives = "" }
WordHunterWoW_QuestEN[97220] = { title = "Philmor's Favor", description = "Every day this week we've been short dockhands.\n\nCare to ease the stress on our cargo schedule?\n\nTake this package to the stockroom entrance of the Gatehouse. You'll find it inside Trias' Cheese shop on the second floor. The mistress, Elaine, will be quite familiar with the deliveries. The Gatehouse often has shipments arriving with more discretion to allow for ceremonial surprises on behalf of the guard's officers.", objectives = "Bring the Gatehouse Shipment to the stockroom entrance located in Trias' Cheese shop in the Trade District", progress = "You looking to fill a crate with our finest aged wheels?", completion = "Oh, dear. You think we want to carry that up the stairs ourselves? Keeping the valuables intact is your responsibility up until the point you drop it off." }
WordHunterWoW_QuestEN[97222] = { title = "Gatehouse Goods", description = "Yes, it's only a flight of stairs, but if it's such a small ask, it should be no problem for you to finish the delivery yourself! \n\nTrias' Cheese isn't part of the Gatehouse or their stocking inventory, but our buildings share a floor.\n\nPlace the crate outside their stockroom door--the guard will send someone for a regular pickup. They will see the package arrival and carry it inside as they return to post.", objectives = "Carry the Gatehouse Shipment up the stairs in Trias' shop and leave it outside the door.", completion = "Yep. There's a reason that hinge opens inwards towards them, so they don't get the door blocked by people leaving stuff anywhere they please.\n\nConsider us professionally acquainted, {class}. \n\nWe respect your business, and expect you to respect ours." }
WordHunterWoW_QuestEN[97223] = { title = "Bloodtalon Matriarch", description = "All of the raptors you see before you are ones I have trained myself. They come from all over Kalimdor, but some of the finest come from the Bloodtalon raptors on the isles off our coast.\n\nOne raptor amongst them, the Bloodtalon Matriarch, is particularly savage and has killed many from our village and has become too dangerous to leave at our borders. If you can strike her down, return with her eggs so that we can raise the hatchlings as allies instead of enemies.", objectives = "Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village.", progress = "The Bloodtalon are known for their cunning and swiftness, and make fine companions when raised from egg to adult.\n\nUnfortunately adult raptors are very difficult to train, and I have tried to capture the Matriarch on more than one occasion. But she had become too dangerous of late.\n\nStill I hope to preserve her legacy by raising her children as companions here in Sen'Jin.", completion = "Thank you, {name}. I am happy we will be able to preserve her bloodline and raise them to be our allies. You have done a great service for our tribe." }
WordHunterWoW_QuestEN[97225] = { title = "Forgotten Loa Idols", description = "When we fled the isles that Zalazane and his ilk now inhabit, we left behind many precious idols that help us commune with spirits we worship: our loa. They are of grave importance to our tribe.\n\nThe followers of Zalazane show no reverence for our loa and have scattered these idols across the largest of the isles.\n\nThis is an action that will not go unnoticed if we are not able to collect these idols, and offending a loa is a grave matter.\n\nGo, find as many loa idols as you can and return them to me.", objectives = "Collect 8 Forgotten Loa Idols from the Echo Isles. Bring them to Master Gadrin in Sen'jin Village.", progress = "Have you found our loa idols, {name}? We must begin our rituals again soon.", completion = "You have done a great deed for our tribe today.\n\nUnlike some tribes, our kinship with our loa is one of reverence and respect, and we owe them much.\n\nI would not want the Darkspear to fall out of favor with them." }
WordHunterWoW_QuestEN[97234] = { title = "Reading Room", description = "Are you here to discuss the deeper meanings of our storied legends? No?\n\nWell, after you're done looking around, can you carry this to the library for me? We're exchanging some of our less popular bodies of work for some more modern writing. I have a list of tomes I'm quite sure the librarian will be able to procure for us within our existing arrangement.\n\nComplimentary club refreshments on us, if you help us out.", objectives = "Bring the wrapped reading material to the Stormwind library.", progress = "Please keep your voice down.", completion = "Let's see here. Roy's Book Club, isn't it? I recognize this wrap technique. \n\nWell, if he says this is what people want to talk about, it's all fine by me. The material we receive back is always in as good of quality as we loaned it, so we know they're treating it with respect regardless of how provoking the words may be." }
WordHunterWoW_QuestEN[97236] = { title = "Fang of Githyiss", description = "A fresh specimen from a beast of this size is quite a find. Perhaps someone in Aldrassil familiar with the study of spiders would be interested in the fang.", objectives = "Deliver the Fang of Githyiss to someone interested in the study of spiders in Aldrassil.", completion = "My, my. How I do love surprises, {name}.\n\nThis specimen will surely help further my studies." }
WordHunterWoW_QuestEN[97237] = { title = "Shelf Picked", description = "I've checked our inventory and all of the selections Mr. Lewells has listed are currently available.\n\nYou will, however, need to procure them off the shelves yourself. Part of our librarian duty is vigilance, and for that, I will resume supervisory bookkeeping.\n\nReturning with the material to Roy on his behalf will not mark yourself accountable for their return; as with his note you're serving as the book club's official courier. Their establishment shall carry that burden.\n\nGood day, {name}.", objectives = "Find each of the reading materials located somewhere in the library and then return to Roy Lewells in Stormwind's Park.", progress = "You forgot what you had to do the moment you stepped through the door, eh? Happens to everyone.", completion = "These are them! Some of them even smell exotic! Fantastic, I can't wait for us to have lively conversations about these writings.\n\nCellar after hours, of course.\n\nThanks for the quick errand run, {name}. As promised, it's on the house. We keep our word here." }
WordHunterWoW_QuestEN[97242] = { title = "Yelmak's Medley", description = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\n\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\n\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood.", objectives = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions", progress = "We discover formulations and recipes by showing old ingredients to new generations, who experiment with it in their own way.", completion = "This type of cattail and speargrass is unique to Orgrimmar. Drinking from Azshara mountain spring water, and nourished by the sweat and blood soaked mineral dust of our rocky land, these herbs contain potent powers locked within.\n\nI'll give these to Yelmak, who may be able to win back Whuut's ear with a hands-on lesson." }
WordHunterWoW_QuestEN[97243] = { title = "Call of Fire", description = "Even though we are in the realm of skywall, this is still the elemental plane. The spirits of all four elements speak to us, if we deign to listen. One among us Windshapers is in particular attunement with the element of fire. A shen'dorei by the name of Olariaan Swiftburn.\n\nBring this to him at the Shrine of Flames in the Gustberry Lowlands. You'll find it tucked away along the edge of the island, west of Valanaar.", objectives = "Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands.", progress = "Yes, {name}? What do you have there?", completion = "So you've brought the torch. Yes, young {class}, I can teach you to heed the call of fire. It will not be easy, but nothing that we do in this realm is ever easy." }
WordHunterWoW_QuestEN[97244] = { title = "Call of Fire", description = "There is an Al'Aketh Skypriest called Faladiel. He was once a caller of the flame and a stalwart Windshaper. Like so many Al'Aketh, he mortgaged his loyalty for power and his hands are now stained with the blood of  his former brothers and sisters.\n\nYou will find Skypriest Faladiel at the farm to the northeast past Valanaar, just to the south of the Shrine of Akir. Kill the betrayer. Bring me his heart. It is a gruesome task, but it is needed for the ritual we are to perform.", objectives = "Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart.", progress = "The heart of a betrayer is a powerful reagent. The flames will eagerly accept such an offering and burn more intensely as it is consumed.", completion = "The Windshapers do not forget, and blood is always paid with blood. It pleases me that you were able to deliver this final, painful reminder of our creed to this traitor.\n\nThis heart will not be all that feeds the flames today, however. There is one other task that needs to done." }
WordHunterWoW_QuestEN[97245] = { title = "Call of Fire", description = "The residents of the Shen'dar Highlands speak of an ancient forest sprite called Kuramaa. They say it lives inside of a twisted stump at the summit of a hill near the highlands Anchor Pylon.\n\nGo to the highlands and find this stump. Rap your fist upon the bark and Kuramaa will appear. Best the spirit in combat, and bring me its wooden mask.\n\nBe warned however, this entity will be exceptionally resistant to much of your magic. Only the touch of flame will lay low the spirit.", objectives = "Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.", progress = "The spirit of Kuramaa is eternal, and it will manifest again when it is needed. It's mask is a source of great power, and will prove invaluable to the ritual we must complete.", completion = "We now have what we need. We will light the eternal flame and commune with the spirits of fire." }
WordHunterWoW_QuestEN[97246] = { title = "Meal Appeal", description = "My son, Migi, always takes off to play with his friends all day. I tell him to pick up a lunch at Borstan's, but I know he almost never does, because he comes home starving. These kids think their games are more important than their own bodies!\n\nPlease, stop at Borstan's Firepit and tell him you're there to deliver Migi's lunch. You can almost certainly find Migi behind Grommash Hold with the rest of his friends.\n\nDuties keep me here during the day and I can't watch over his every meal.", objectives = "Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally.", completion = "Of course. Migi's parents and I have an arrangement to give Migi a bagged lunch every day, but I can only ensure the boy gets his food if he actually comes in to pick it up.\n\nSometimes, he doesn't pick up his meal multiple times a week, and I wonder where he gets the energy to stay out and play." }
WordHunterWoW_QuestEN[97249] = { title = "Favorite Food", description = "Now that I know his parents worry about how much he's actually filling that belly, I've got an idea. \n\nThey made me promise not to pack the same meal every day, so Migi grows a taste for more than one thing. Still, whenever the smoker's full and we're making sweetglazed hog belly sandwiches, he always shows up for lunch. We've started crumbling the leftover crispy glazed bits as a topping--something we can add daily. \n\nTake this to him. Maybe he'll start showing up early and bringing friends!", objectives = "Bring Migi's Lunch to him behind Grommash Hold", progress = "I think we can win this one...", completion = "Borstan's Meats? Is that for one of us?\n\nOh!\n\nWow... this smells really good! Yummy.\n\nThanks for bringing me my lunch. I can tell what Borstan is going to be serving daily when my friends and I walk the road to Grommash Hold, by the smells alone. This tastes like my favorite, the sweetglaze! But it's different. I like the strong flavored crumbs.\n\nIf it's going to be this tasty every day, I think we need to stop our game to take our lunch together!" }
WordHunterWoW_QuestEN[97250] = { title = "Wrongly Blamed, Justly Corrected", description = "Traveler, have you plans to head toward Dustwallow Marsh? I have heard mutterings that a few human soldiers have taken a stand at its border and are toppling the landmarks left behind by our tauren pathfinders.\n\nRumor has it that a favored tavern has burned to the ground, and in typical Alliance fashion, they immediately cast their blame onto the Horde! I cannot know whether there is any truth to their claim, but their incursion onto OUR land must not stand.\n\nKill first, investigate later!", objectives = "Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.", completion = "So the rumors were true! I expected as much, tensions have been rising along the eastern coast for some time. I knew it would only be a matter of time before conflict crept into our territory.\n\nHowever, I am skeptical that we played a role in the tavern's destruction. Too many Horde civilians rely on that route for trade and travel. Perhaps you could investigate further if you find the time.\n\nIn any case, today's deed is a victory for the Horde, and a stern warning to the Alliance!" }
WordHunterWoW_QuestEN[97253] = { title = "Parts and Pieces", description = "Hey, got a sec?\n\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\n\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?", objectives = "Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.", progress = "Not another word out of you until your pockets are jingling with metal!", completion = "Whooooa! Nice one, pal! You saved me from another one of Gagsprocket's unbearable lectures on the cost of metal. More importantly, I can jump right into building my next prototype.\n\nUhhh, I didn't have a reward planned... Do you like boxes?" }
WordHunterWoW_QuestEN[97257] = { title = "Call of Fire", description = "Now we will perform the ritual. \n\nI will place the materials onto the altar and call forth the spirits of flame. If the offering is accepted, they will appear and light the Eternal Flame. You will then hold your torch forth and capture the flame.\n\nCarry the lit torch to Valanaar and place it in the Brazier of Eternal Flames. You must do so quickly, for the flames of the Firelands are quick to dissipate here in Skywall.", objectives = "Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\n\nYou must deliver the Eternal Flame to Valanaar before the timer runs out.", progress = "You have done well to come this far. You do the Windshapers honor, {name}.", completion = "It is done. The Eternal Flame burns once again.\n\nYour trial is now complete. I am pleased to present you with your Fire Totem. Use this icon of power well in your travels, {name}. \n\nJust remember, the power of the elemental plane serves those that respect it, and consumes those who do not. This is our way." }
WordHunterWoW_QuestEN[97263] = { title = "Your Package Has Arrived", description = "<Several misplaced packages have been left by the mailbox. You note that one of them is marked for delivery from Aerie Peak, to Ironforge, to Eldrun Stormbreaker. It is marked \"urgent.\">", objectives = "Deliver Eldrun's misplaced package.", progress = "What's that you've got there?", completion = "What! I've been going to the mailbox by the bank every day looking for this package! This city needs to figure out its layout. Not easy to navigate like Aerie Peak!\n\nLet's see what I've got... totem carving tools... spare axe... some kind of goblin device? I didn't order that! Ah, I'll just send it back.\n\nEr, uh... I mean... thank you for bringing all of this to me. Here's a little something for your trouble." }
WordHunterWoW_QuestEN[97265] = { title = "Hate the Hatefury", description = "Ever strike a deal with a satyr, mon?\n\nI have. How could I resist? The promise of power, knowledge far exceeding what any ordinary tome could offer... all alongside an eager and charismatic minion. What more could I ask for?\n\nBah, of course they would never bend the knee to a mortal. I bargained when I had nothing, only to be cast aside with even less.\n\nNow, I want revenge. Revenge against the Hatefury. Raid their camp to the northeast! Stain the dirt with their foul blood.", objectives = "Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village." }
WordHunterWoW_QuestEN[97275] = { title = "Whuut's the Rush", description = "Whuut is a prodigy. That much is true. But he doesn't yet have the experience, wisdom, and time on the stirring rod to know how to respect alchemical processes.\n\nHe is exhausting all of the rarest and most exotic reagents we have available without pausing to practice and refine his basic skills.\n\nGive him this potion I've brewed with a quick tonic method. He'll reconsider everything he's doing when he learns how local remedies and careful touch are the first true mastery.", objectives = "Give Yelmak's Potion to Whuut.", progress = "Alright, what's next... Black Lotus, Mountain Silversage...", completion = "Grorru--whaa?\n\nYou say Yelmak made this potion from speargrass and cattail with no other reagents? I didn't know chemists had any real need for these common plants we see every day.\n\nMaybe he's right. There could be a lot I'm missing out on by skipping to the most rare and least-studied flora first.\n\n{name}, take your pick from one of these potions I brewed earlier. I appreciate you taking the time to visit our shop." }
WordHunterWoW_QuestEN[97277] = { title = "Grund and Gozwin", description = "Oi, had me back turned gettin' the boar roast ready when I heard me pal Gozwin screamin' fer his life!\n\nWicked fangs and a blur are all I saw when I turned. Such huge paws! A snow leopard was draggin' its gnomish catch away. I grabbed me shotgun and fired above the beast. It dropped him and sprinted off.\n\nLuckily, it hadn't done more than give ol' Goz some deep scratches.\n\nHead back to camp in the northwestern hills and retrieve Gozwin's Mechanic's Log. Kill that snow leopard too if you see it!", objectives = "Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler.", progress = "Poor Goz is more concerned for his mecha-walker than himself. Says if anyone gets a hold of that mechanic's log he's greased. Hah! That's why I told him he should just leave his work at home!", completion = "Aye, I'm not surprised to hear that snow leopard was makin' a meal of the boar we were fixin' fer roastin'!\n\nGoz will have one less thing to stress about now that you brought back his log book. Maybe now he can focus all his energy on gettin' back on his feet.\n\nThanks, {name}. Take a little something as a token of my appreciation, fer makin' the trek, and fer protectin' the hills." }
WordHunterWoW_QuestEN[97279] = { title = "Wayward Weapons", description = "With an influx of new recruits like yourself, it's been hard to keep our weapons supplied. Our weaponsmith, Kzan, is running low on training weapons and I'd like to see what kinds of skills you possess to get an idea of what I have to work with. Luckily for you, I have a solution to both.\n\nWhile you're out there cutting your teeth on boars, salvage six abandoned training weapons. Our failed recruits left them laying on the ground. Once you do, return them to our weaponsmith Kzan behind me in the Den.", objectives = "Collect 6 Abandoned Training Weapons, then return to Kzan Thornslash in the Den.", progress = "Throm'ka, {class}. Gorak told me I should be expecting you. It is good to see you in one piece!\n\nWere you able to collect the training weapons I requested?", completion = "Thank you for returning these weapons, {name}. I will get to work repairing them for the next wave of recruits." }
WordHunterWoW_QuestEN[97281] = { title = "A Simmering Storm", description = "<Before you is a strange orb and with a dull surface. When picked up a small electrical current seems to vibrate from within. Upon closer inspection, it looks as if a dark mist swirls within and every so often a small electrical spark can be seen.\n\nIt is clear the harpy was using it for some purpose. Perhaps Rezlak would be interested in this object?>", objectives = "Bring the Dull Stormy Orb to Rezlak near Drygulch Ravine.", completion = "Woah, where did you find a neat thing like that? Ya know it reminds me of the other thing my boss Gazlowe always used to tell me..." }
WordHunterWoW_QuestEN[97282] = { title = "Stormy Potential", description = "\"Rezlack, when an opportunity come's knocking make sure you're ready to seize it.\" That's another gem Gazlowe taught me and that's exactly what I intend to do.\n\nThis orb doesn't seem damaged, it just looks like it's out of juice, but I've the idea to supercharge it back to full strength!\n\nThere are a bunch of thunder lizards in a gorge west of here. They have organs that hold a strong electrical charge that would be perfect for this.\n\nGo harvest some and bring them back to me!", objectives = "Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine.", progress = "It might come as a surprise that with a name like thunder lizard they shoot lightning instead of roaring like thunder.\n\nWell, they do. Shoot lightning, I mean.\n\nTrust me, it's a lesson you only get to learn once if you're lucky.", completion = "Hey, thanks pal! You've been a really big help to me here and I appreciate it.\n\nHere's to hoping I can get this all charged up using these organs. I bet it'll make those no good harpies think twice about attacking my caravan again. I sure hope this works.\n\nEither way you've done your side of the deal. Take this for your trouble." }
WordHunterWoW_QuestEN[97284] = { title = "Vahlarriel's Vengeance", description = "If Malem is still alive, then I suspect the Burning Blade orcs are expecting someone to come searching for her soon enough. They will certainly be ready for a fight.\n\nI would prefer if you kept a low profile and stayed out of their way, but the far more likely reality is that they will be looking to meet you, blade to Burning Blade, at every opportunity.\n\nSo how about we plan to keep score from the start. Kill as many as you can, and I'll make it worth your time.", objectives = "Slay Burning Blade orcs at Thunder Axe Fortress in the Desolace, then return to Vahlarriel Demonslayer at Nijel's Point." }
WordHunterWoW_QuestEN[97286] = { title = "Research Access", description = "", objectives = "Your actions show you are one who respects knowledge. The library is open for use in your studies.", completion = "Your actions show you are one who respects knowledge. The library is open for use in your studies." }
WordHunterWoW_QuestEN[97287] = { title = "Shrewd Negotiations", description = "You have done well to infiltrate the city of mages, but I believe it is time for us to be more... negotiatory.\n\nAs much as it pains me to admit, there is no other place on Azeroth with such a vast knowledge of the arcane. My brilliant work still pales in comparison to the ancient wisdom the Kirin Tor have amassed over the years. I think it's high time we are granted access to this exclusive order, don't you think?\n\nTake the mote you acquired. They will surely give anything to get it back. Anything.", objectives = "Speak with Archmage Celindra in the City of Dalaran." }
WordHunterWoW_QuestEN[97288] = { title = "Unending Torment", description = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\n\nSomeone in the Undercity would know more about this unique abomination.>", objectives = "Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.", progress = "What have we here?", completion = "Oho! I believe I know this head. A cruel joke by our Dark Lady. A delicious one at that.\n\nI think I have a use for this." }
WordHunterWoW_QuestEN[97289] = { title = "Unending Torment", description = "We craft abomination heads all the time, but this one is special. It belonged to a Grand Marshal of the alliance once. A particularly unpleasant one. Othmar, I believe its name was. The Dark Lady had the pleasure of dispatching of this one herself.\n\nOoh the secrets it could tell if it could talk. And it can! If we reattach it to an appropriate host.\n\nGo ahead and place it next to the available body in the next room. But don't attach it. Not yet.", objectives = "Bring the Head of the Baron to the body of Othmar in the Undercity.", progress = "<The abomination remains lifeless without a head to control it.>", completion = "<The body twitches to life, panicking as it relives its final moments.>\n\nYou..." }
WordHunterWoW_QuestEN[97290] = { title = "Unending Torment", description = "You... abomination...\n\nWhy should... help you...\n\nBe gone...", objectives = "Report your findings to Master Apothecary Faranell in Undercity.", completion = "Not cooperating, eh? Excellent. I always love a challenge." }
WordHunterWoW_QuestEN[97291] = { title = "Unending Torment", description = "With the head reattached, all we need now is to bind it to the Dark Lady's will. This should not be a problem. The beast barely has brains left as it is after all the beatings it's taken.\n\nWe simply need to motivate it.\n\nFetch me a Toxic Skullcap from Miss Grisette in the Trade Quarter. Oh, and some Blisterweed from our local herbalist trainers, the Alliestars. Feel free to just take some, they owe me. And lastly a bit of Essence of Agony. Any old poison vendor should do.\n\nWe have a potion to make!", objectives = "Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.", progress = "It will be ever so lovely to have our lost sheep returned to the fold, don't you think?", completion = "These will do nicely. We will see how much bravado our honored guest retains after he is subjected to my masterpiece." }
WordHunterWoW_QuestEN[97292] = { title = "Unending Torment", description = "I have concocted a lovely serum that our new guest is sure to find quite... stimulating.\n\nTake this. Feed it into the workings dripping from above him. Let's see if we can't show him why it's in his best interest to serve loyally.\n\nAnd try not to drop it. I can't afford a new assistant.", objectives = "Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.", progress = "For Othmar's crimes against the Dark Lady, placing him under that oozing specimen is the least he deserves.\n\nAnd it's funny...", completion = "Excellent. We'll let his flesh simmer for awhile. Give him time to acclimate to his new home.\n\nI have no further use for the wretch for now, but we shall keep an eye on him. I have many plans for Othmar's future." }
WordHunterWoW_QuestEN[97326] = { title = "Rocks to Rests", description = "Hey! You've got time to help us out! I know you do, I can tell by the way you smiled watching the game we're playing.\n\nThis spot behind Grommash Hold is nice because it's clear enough for us to set up our figures. But what stinks is we don't have enough rocks for chairs or tables.\n\nYou're big and strong... d'ya think you could carry back some medium sized rocks, smooth enough to sit on if we need a rest?", objectives = "Return 8 Smooth Boulders to Thra behind Grommash Hold.", progress = "It's nice to not have to always sit in the dirt!", completion = "How can you even hold all of those boulders!\n\nThose are great. Most even have a nice flat side, too. Now that you carried them all the way over here we can scoot them around in the dirt, right where we want 'em.\n\nThanks, {name}!" }
WordHunterWoW_QuestEN[97328] = { title = "Anything of Value", description = "<As you sift through the debris left behind by a horrible zeppelin crash directly above, you find evidence of a hefty shipment of supplies that has long since been plundered of all its value. Even the shipping labels have been torn and shredded, leaving only the words 'Booty Bay' barely legible on one.\n\nCountless two-toed footprints and several patches of divotted earth all lead toward ruins in the northwest.>", objectives = "Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay." }
WordHunterWoW_QuestEN[97329] = { title = "Where's the Key?", description = "You! Yes, you! Come here, keep your voice down!\n\nI screwed up big time. I managed to secure a sweet deal for Booty Bay to use their zeppelin tower for expedited deliveries and on our very first route I saw a huge bird--err, got SHOT DOWN just to the east of here!\n\nI survived the crash, unfortunately, but before I woke up, I was already being dragged by my ears! Now I'm surrounded by bloodthirsty trolls and locked in a cage!\n\nLook, I just need the key, okay? I can escape on my own.", objectives = "Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark." }
WordHunterWoW_QuestEN[97331] = { title = "Zimmix's Great Escape", description = "Wait, wait, don't go yet!\n\nI know I said I just needed the key but... well, they caught me once, they could do it again, right? I'm just one goblin, and there's hundreds of trolls around here!\n\nYou've already put enough of a dent in their numbers to get this key, so it should be easy enough to stand guard while we mosey on out of here, huh?", objectives = "Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue." }
WordHunterWoW_QuestEN[97485] = { title = "Traditions of the Bluff", description = "Blessings of An'she, friend.\n\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\n\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\n\nYou will find a mat and incense at the ceremonial site.", objectives = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Ceder Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\n\nCombine the items and sprinkle the incense off of Hunter's Rise.", progress = "There are many occasions one may choose to spread incense to the winds. You could be asking the Earthmother to watch over someone, bless a hunt, celebrate an occasion, or even to seek guidance from our ancestors.\n\nOr it could be something else entirely.\n\nThough the act is done with reverence, it is not strictly a ceremonial affair. Typically there are certain traditional steps observed when performing this act, but many tribes have differing practices.", completion = "You have done well, friend.\n\nI thank you for taking the time to perform one of our time-honored traditions, {name}. I hope that as you travel you will find plenty of occasions you wish to give thanks for.\n\nShould you ever wish to perform the ritual again, you should be able to repurchase the components I sent you to collect.\n\nGo with An'she's warmth." }
WordHunterWoW_QuestEN[97538] = { title = "Pigments for Paints", description = "Greetings, friend. I wonder if I may ask a favor of you? I have just run out of red pigment for my paints, and I am looking for one with younger hooves to make the long journey into the Stonetalon Mountains on my behalf.\n\nIn the middle of the mountain pass there lies a large circular lake, Mirkfallon Lake, that has a unique plant that grows within its waters. The pods of this plant, mirkweed, turn a vibrant red when dried. Gather the pods of this plant for me, and I will reward you well for your efforts.", objectives = "Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake.", progress = "You have returned! Were you able to find the mirkweed plant pods in Mirkfallon Lake?\n\nWe tauren have used this plant pigment in our paints for generations, so any amount you manage to bring would be appreciated. Though there are many ways to get a red pigment, I find the mirkweed to give the richest and most vibrant hue of the methods I'm familiar with.", completion = "Ah, thank you {name}.\n\nIt means much to me to have you venture all the way out there for what must seem a trivial notion from an old tauren, but with your kindness I will have enough pigment for the rest of the season.\n\nThank you for supporting my livelihood, and I will strive to create something magnificent with the pigments you have brought." }
WordHunterWoW_QuestEN[97539] = { title = "Silky Sutures", description = "This encampment is being left to rot. The siege damage stands, unrepaired, as if neglect were policy. I won't permit that same decay here. The infirmary answers to me, and I intend to keep it functional.\n\nWe are nearly out of supplies. I'm going to need more equipment--enough to keep the workers and guards on their feet.\n\nUnder pressure, we can make quite an effective field suture using twisted spider silk.\n\n{class}, bring me some from the spiders that stalk these highlands.", objectives = "Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands." }
WordHunterWoW_QuestEN[97558] = { title = "Hides for the Forsaken", description = "One part of undeath no one mentions is what happens when we are injured. How does the skin of an undead heal itself?\n\nWell, it doesn't.\n\nOurs is a cursed life, {name}. We must take from the living to further our own existence.\n\nWhen we sustain an injury, we must replace our skin which usually means animal hides. Since different hide thicknesses are better for different places on our bodies a variety is key!\n\nBring me wing membranes of a duskbat, hides from a darkhound and skin of a Vile Fin murloc.", objectives = "Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.", progress = "Have you gathered the skin I inquired about? Our stocks are running low.\n\nIt may seem odd to ask for murloc skin but it works well for internal membranes, or surfaces like cheeks or mouths.\n\nSimilarly, the duskbat wing membranes are especially suited for more delicate areas, like faces or fingers. It prevents the skin from being too... thick.", completion = "Ah, excellent! Thank you for acquiring these. I can promise they will be put to good use." }
WordHunterWoW_QuestEN[97583] = { title = "WRIGGLE.", description = "<The little slime seems delighted and is attempting to mirror your motions as you dance. It begins to look weary though.\n\nThe little slime hovers over a bit of sludge and absorbs it, looking slightly rejuvenated.\n\nIt seems all of this dancing has tuckered it out. Perhaps someone in the Undercity canals sells more of this nutritious sludge?>", objectives = "Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention.", progress = "<The slime seems to regard you with interest.>", completion = "<The slime shudders with newfound energy. It seems to want to follow you, now that it has associated you with food.>" }
WordHunterWoW_QuestEN[97891] = { title = "Prompt Potion Runner", description = "You! Quickly, I need you to bring this potion across the slime canal to Doctor Martin Felben in the Apothecarium!\n\nIt has a very limited shelf life, and no I can't go myself, my knees rattle and pop out if I attempt to run.\n\nJust another lovely side effect of undeath, apparently.\n\nBut we're wasting time! Here, take this and go!\n\n<Alessandro makes a shooing motion.>", objectives = "Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit.", completion = "Ah, marvelous! I had been waiting for Alessandro's potion to arrive. The last six he sent destabilized along the way, but you've made it just in time!\n\nHere, take this for your effort. That is all for now, unless you have other business with me?\n\nIf not, remove yourself so I may continue my experiments unhindered." }
WordHunterWoW_QuestEN[97894] = { title = "Business in Auberdine", description = "Pleasure to make yer acquaintance! Name's Borgus, of the one and only Steelhand family. You can always count on a Steelhand fer a fair deal!\n\nA few weeks back me brother Gorbold joined up with a merchant stall in Auberdine. Plenty of coin to be made supplyin' ships there, let me tell you! Lucky sod.\n\nI haven't heard from him since--mind checking on him if yer heading that way?\n\nThere's a new ship in the harbor that will take ye straight there. Head to the southern-most dock; can't miss it!", objectives = "Check on Gorbold Steelhand in Auberdine in Darkshore.\n\nBorgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there.", completion = "Old Borgy sent you? Always looking out for me.\n\nWe could certainly use another set of hands around here. Business has all but stopped with the recent tragedy, and I think you could help set things right." }
WordHunterWoW_QuestEN[97899] = { title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", objectives = "Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There ya have it, directions for your very own Mana Well. Most folks don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to try it out.\n\nNo camp is complete without a campfire. You'll need one of those as the basis of your camp. Most cooks can teach you to make a fire. Check in with someone who can train you in cooking if you haven't already learned the basics." }
WordHunterWoW_QuestEN[97900] = { title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", objectives = "Speak with Dwukk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97901] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Jhag in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can craft your very own Enchanted Lute. Most folks don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to try it out.\n\nNo camp is complete without a campfire. You'll need one of those as the basis of your camp. Most cooks can teach you to make a fire. Check in with someone who can train you in cooking if you haven't already learned the basics." }
WordHunterWoW_QuestEN[97902] = { title = "Camping 101: Engineering", description = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells.", objectives = "Speak with Mukdrak in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Reagent Bot. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97903] = { title = "Camping 101: First Aid", description = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a {class}.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.", objectives = "Speak with Rawrk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "I can teach you once you've gained some skill with your profession.", completion = "There you have it, you can now craft your very own First Aid Kit. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97904] = { title = "Camping 101: Fishing", description = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.", objectives = "Speak with Lau'Tiki near Sen'jin Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "I can teach you once you've gained some skill as a fisherman.", completion = "Dere ya have it, ya be craftin' your very own Fish Bowl. Most folk don't be carin' much for camps being set up in da center of town, so ya be needin' ta head into da wilderness if ya be wantin' to try it out.\n\nNo camp is complete without a campfire, mon. Ya be needin' one of dose before ya be startin' up your camp. Most cooks be teachin' ya ta make a fire. Check in with someone who can train ya in da culinary arts if ya haven't already learned da basics." }
WordHunterWoW_QuestEN[97905] = { title = "Camping 101: Herbalism", description = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate.", objectives = "Speak with Jandi in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "Dere ya have it, ya be craftin' your very own Incense Candle. Most folk don't be carin' much for camps being set up in da center of town, so ya be needin' ta head into da wilderness if ya be wantin' to try it out.\n\nNo camp is complete without a campfire, mon. Ya be needin' one of dose before ya be startin' up your camp. Most cooks be teachin' ya ta make a fire. Check in with someone who can train ya in da culinary arts if ya haven't already learned da basics." }
WordHunterWoW_QuestEN[97906] = { title = "Camping 101: Leatherworking", description = "You've become a leatherworker. Good for you, {class}. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels.", objectives = "Speak with Karolek in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, your very own camp tent. Most folk don't care much for tents being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97907] = { title = "Camping 101: Mining", description = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.", objectives = "Speak with Krunn in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Lodestone. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97908] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Camp Chair. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97914] = { title = "Expanding Horizons", description = "Auberdine is a humble place, {class}. You will not hear its name spoken in the boughs of Darnassus. Most reference only what the Sundering took from us--the thriving cities of Ameth'Aran, Bashal'Aran, and... Lathar'Lazal.\n\nYet Auberdine remains in their shadow.\n\nI would see our work here recognized. A new vessel connects us to the kingdom of Stormwind, bringing life and supplies to our shores. I beseech you join its next voyage, and bring this letter to a human called Baros Alexston.\n\nMake our home known.", objectives = "Bring Thundris' Letter to Baros Alexston in Stormwind.\n\nThundris mentioned a boat in Auberdine that can take you there.", progress = "I can smell the sea on you, friend!\n\n<Baros laughs.>\n\nWhat brings you to Stormwind?", completion = "<Baros opens the letter and begins to read it, his smile fading.>" }
WordHunterWoW_QuestEN[97915] = { title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", objectives = "Speak with Alchemist Mallory in Elwynn Forest near Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Mana Well. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97916] = { title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", objectives = "Speak with Smith Argus in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97917] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Betty Quin in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can now craft your very own Enchanted Lute. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97918] = { title = "Camping 101: Engineering", description = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells.", objectives = "Speak with Sprite Jumpsprocket in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Reagent Bot. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97919] = { title = "Camping 101: First Aid", description = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a {class}.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.", objectives = "Speak with Michelle Belle in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own First Aid Kit. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
