WordHunterWoW_QuestEN[97969] = { title = "Camping 101: Leatherworking", description = "You've become a leatherworker. Good for you, {class}. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels.", objectives = "Speak with Indari Sunseam in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, your very own camp tent. Most folk don't care much for tents being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97970] = { title = "Camping 101: Mining", description = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.", objectives = "Speak with Messana Crestwind in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Lodestone. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97971] = { title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", objectives = "Speak with Mendalass Tattermend in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Camp Chair. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97972] = { title = "Camping 101: Tailoring", description = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized.", objectives = "Speak with Taleen Shimmerthread in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Rallying Banner. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97973] = { title = "Camping 101: Tailoring", description = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized.", objectives = "Speak with Taleen Shimmerthread in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Rallying Banner. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[97977] = { title = "Nature's Call", description = "The Gnarlpine furbolg would not turn on their ancient allies so readily. We must learn more of their plight.\n\nSearch their abandoned homes for totems. If any survived the chaos of their departure, their engravings may tell us more of what happened here.\n\nYou'll find their camps along the western edge of the glen, though the grell and grellkin may have scattered them beyond.", objectives = "Collect 4  Gnarlpine Totems and bring them to Tarindrella.", progress = "Don't worry about any larger totems you might find. I wouldn't know what to do with them if you found a way to get them!", completion = "Oh, it's even worse than I thought.\n\nThese engravings tell us that the Gnarlpine began having nightmares of being wiped out by some great shadow. Before long, that fear turned to rage--and the shadow to their former elven friends. To be aware of your own mind slipping away from you...\n\nOur only hope is that this may help us better understand what is happening on Teldrassil. Thank you for your aid, {name}." }
WordHunterWoW_QuestEN[97979] = { title = "The Goddess Provides", description = "You are born kaldorei--the children of the stars--and have inherited a birthright unlike any other in this world. Elune's grace may illuminate our strengths, helping our strikes hit true, or it may help conceal us just as the moon may eclipse the sun.\n\nOur Long Vigil after the defense of Mount Hyjal has ended, and we have joined an Alliance of others--which you will meet in due time. For now, you are nestled in the boughs of Teldrassil.\n\nDemonstrate Mother Moon's gifts, and bask in her blessings.", objectives = "Cast Elune's Light and Shadowmeld.", completion = "You have seen what our goddess provides. Use it well, and she will never forsake you." }
WordHunterWoW_QuestEN[97985] = { title = "Thundering Hearts", description = "Fascinating, aren't they? This is the first time I have ever been privy to the secrets of abomination creation.\n\nI have been studying these notes, and it appears we need a heart. A massive one!\n\nI hear there is a thunder lizard there of impressive size called Stormheart, that patrols along the canyon edge in Thousand Needles. With a name like that it must have the perfect heart. I must have that heart!\n\nOh, also I suggest you bring friends. Stormheart isn't known for being docile.", objectives = "Slay Stormheart in Thousand Needles and acquire its heart." }
WordHunterWoW_QuestEN[98013] = { title = "Swelling Forces", description = "Steel yourself for your time in the ruins, young one... you will not be granted free passage there.\n\nScores of cursed Highborne, now known as naga, roam the once great city. Travel northeast and dispatch them from this land.\n\nWhat they once were... is no more. If they aid the Twilight's Hammer, they can bring only further pain to the forests that once gave them shelter.\n\nWar is what they seek, {class}. War... is what we will bring.", objectives = "Eliminate 12 Stormscale Myrmidons, 8 Stormscale Sorceresses, and 6 Stormscale Warriors for Arbal at the Grove of the Ancients.", completion = "Do not fret, young one. To pillage one's own home for some dark master...\n\nIt is unforgivable." }
WordHunterWoW_QuestEN[98021] = { title = "Journey to Sentinel Hill", description = "If you'd like to get started doing some good in our world, I'd recommend reporting to a man named Gryan Stoutmantle in Westfall to the south, at the settlement known as Sentinel Hill. His people are in need of aid.\n\nAfter journeying here from another plane of existence, the problems our lands face may seem small. I assure you, the aid you provide to those impacted by such problems means everything to them, and you will grow stronger for your labors.\n\nGood luck out there, adventurer!", objectives = "Report To Gryan Stoutmantle at Sentinel Hill in Westfall.", completion = "I've been begging Stormwind for aid for months and he sends me a skinny elf? Well, beggars can't be choosers I suppose.\n\nWelcome to Westfall, {class}. Let's see if we can't put you to work." }
WordHunterWoW_QuestEN[98024] = { title = "Journey to the Crossroads", description = "After journeying here from the elemental plane, the problems our lands face may seem small. Rest assured, the dangers the horde faces are very real, and you will grow formidable should you survive your service.\n\nIf you'd like to get started doing some good in our world, travel southwest to the vast lands known as the Barrens. There is a settlement there known as the Crossroads. The proud citizens there are ever in need of aid.\n\nGo with honor, adventurer!", objectives = "Report To Thork at The Crossroads in The Barrens.", completion = "What's this? An elf? And you say the Warchief sent you?\n\n<Thork grunts sharply as he looks you up and down.>\n\nYou look a little skinny to me, but it matters not. Out here you'll either thrive and survive, or you'll die. That is the way of things in these lands." }
WordHunterWoW_QuestEN[98025] = { title = "WANTED: Jai'vhanel", description = "Attention!\n\nA reward is being offered for the death of the owl \"Jai'vhanel\" also know as \"Swordfeather\".\n\nUnfortunately this owl has gone mad and has begun to attack travelers as they journey along the road near Auberdine.\n\nJai'vhanel was last seen north of the Ameth'Aran ruins near the mountain base. Bring back one of her jet black feathers as proof of her death.\n\nReward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine.\n\nThe Auberdine Village Council", objectives = "Find and slay the owl known as Jai'vhanel and take one of her feathers. The black owl was last seen north of the Ameth'Aran ruins near the mountain base. Report the death of Jai'vhanel to Sentinel Glynda Nal'Shea in Auberdine.", progress = "Greetings {class} - what may the Sentinels assist you with today? Perhaps you are here to inquire about the bounty on Jai'vhanel?", completion = "It is good to know that issue has been taken care of, but it saddens me that we could not find another way. Jai'vhanel had been somewhat of a guardian of this area for quite some time, and I am not sure what could have caused her decent into madness.\n\nRegardless, thank you for your service today, {class}. The roads to Auberdine are safe for travel once again." }
WordHunterWoW_QuestEN[98027] = { title = "Gleaming Crescent Necklace", description = "<The silver necklace in your hands gleams gently as you examine it. The small crescent moon shape seems similar to other night elf symbols you've seen before.\n\nUpon flipping the necklace over there is a small inscription: \"Alor'lormah, Maliynn\". Perhaps it belongs to Maliynn in Astranaar?>", objectives = "Deliver the Crescent Necklace to Maliynn in Astranaar.\n\nProvided item:", completion = "Oh my! I can't believe you found this. I thought I had looked everywhere!\n\nI had lost it when I went to deliver supplies to one of our outposts, but after searching along the road I had given up.\n\nThank you for bringing this back to me. It was a gift from my late parents, and I can't express how much it means to have it back." }
WordHunterWoW_QuestEN[98028] = { title = "Baron Marinous", description = "All that remains of the powerful elemental is a globe of what seems to be pure water, clouded by some unknown substance. The edges of the sphere seem to be clear until you turn it--as if the cloud actively prevents you from peering within.\n\nWhatever happened to it--and to the ruins it was guarding--is still active in some way.\n\nOnly Onu, the Ancient of Lore at the Grove of the Ancients to the far south, would have a chance at knowing more.", objectives = "Bring the Clouded Water Globe to Onu at the Grove of the Ancients in Darkshore.", progress = "I can sense something far older than you in my presence, {race}... what have you brought me?", completion = "<Onu appears surprised--or as surprised as an ancient can appear.>\n\nStairs descending down in Mathystra? Could be it be?\n\n<Onu shakes his head.>\n\nI must confer with the others on this. For now, know that it is good you uncovered this before the naga... or their cult allies.\n\nPlease accept this as thanks for your efforts. It is no small feat to defeat an elemental guardian." }
WordHunterWoW_QuestEN[98042] = { title = "It's All Fun and Games Until...", description = "<As you tear away the single page from the Twilight Tome, a foreboding voice floods your mind, uninvited.>\n\nThey have failed.\n\nYou will be forgotten.\n\nThey will lose the eye they gained.", objectives = "Obtain a Peerless Eye from a Twilight Disciple or Thug at the Master's Glaive in Darkshore and find someone in Auberdine who is willing to take it.", progress = "You look troubled. I am listening.", completion = "<Thundris does not speak for some time.>\n\nThis bears the mark of an ancient evil, {class}. I will see it brought to Darnassus at once for further study.\n\nAnde'thoras-ethil." }
WordHunterWoW_QuestEN[98046] = { title = "Crown of the Earth", description = "<Arch Druid Fandral Staghelm's gaze narrows.>\n\nYou're still here?\n\nTake the phial and get out of my sight, {class}. It is clear my answers do not lie in the waters, just as they did not before. \n\nPerhaps one of the priestesses in the Temple of the Moon to the south will dispose of it.\n\n<Fandral looks away, no longer speaking to you.>\n\nI must look elsewhere if this is to work...", objectives = "Bring the Drained Vessel to Lariia in the Temple of the Moon in Darnassus.", progress = "How may I aid you?", completion = "Do not mind the Arch Druid, {name}. He bears the weight of much in Malfurion's absence.\n\nWait! Some drops yet remain in the phial! Perhaps that is why his incantation failed?" }
WordHunterWoW_QuestEN[98059] = { title = "Hillsbrad's Hoard", description = "Hillsbrad's council hasn't answered our new magistrate's letters. The last word I pried out of a passing merchant from the town did little to justify their silence.\n\nWe're only asking for a small platoon--yet I'm told multiple siege ballista rest in pristine condition within a walled-off compound.\n\nWalk into their town hall like a citizen returning a census request, and place this neatly upon the bookkeeping table.\n\nReturn to me when the deed is done.", objectives = "Place the Sealed Company Request you were given on the bookkeeping table within Hillsbrad's town hall." }
WordHunterWoW_QuestEN[98065] = { title = "Crown of the Earth", description = "You must bring this to Tyrande at once! I will transfer it to a more ceremonial container for you.\n\nDo not be afraid. The High Priestess of Elune is firm, but kind. She protects all who enter Darnassus, and carries our goddess' light to all.\n\nShe will be glad to receive this sacred water. You will find her directly above us.", objectives = "Bring the Moonwell Remnants to Tyrande Whisperwind in the Temple of the Moon in Darnassus.", progress = "Please state your business. I have a city to run, and a people to lead.", completion = "Staghelm has done much in my beloved's absence, but he is not Malfurion. And he does not run the affairs of Darnassus--that burden is mine alone.\n\n<Tyrande's face settles.>\n\nI apologize. As you have likely seen, we have many challenges to overcome.\n\nFandral is Arch Druid for now, and I ask you respect his station. But his doings pertain to druidism, and mine not only to Elune but indeed to lead our people as she wills.\n\nEvery drop of this water is blessed by our goddess. I thank you for saving it." }
WordHunterWoW_QuestEN[98067] = { title = "Eyes of the Sentinels", description = "General Feathermoon ensures all sentinels have time to pray to Elune. A proper huntress wields not blade alone, but gifts of the goddess to overcome our enemies.\n\nYou may help with my daily duties. Place sentinels around the city--start with the tunnels leading beneath Cenarion Hold to the north, the bank at the center of town, the inn in the Craftsman's Terrace to the northeast, and the city gates. The guards can assist you.\n\nSomething is amiss in Teldrassil--we must remain vigilant.", objectives = "Place Sentinel Owls at the entrance to the Cenarion Hold depths, the Darnassus Bank, the Craftsman's Terrace Inn, and the City Gate for Sentinel Dalia Sunblade in the Temple of the Moon in Darnassus.", completion = "I thank you for your aid. Though I find peace in the daily rituals, it is nice to have a moment to reflect instead." }
WordHunterWoW_QuestEN[98069] = { title = "Stolen Freewind Supplies", description = "Those wretched harpies! They attacked the last caravan I had scheduled to deliver supplies to Freewind Post. We have enough supplies for the moment, but without more supplies, we'll run short soon.\n\nI'm not sure what the harpies plan to do with the extra supplies, but I would be grateful if you would recover them for me. They make their lair west of here. They can be found both at the base of the cliffside and inside a cave at the top.", objectives = "Bring 8 Stolen Freewind Supplies to Jandia in Freewind Post." }
WordHunterWoW_QuestEN[98070] = { title = "Stop the Screeching", description = "The Screeching Canyon is home to a local band of harpies known for their ferocious nature and raiding tactics. They have ambushed the last few supply caravans that have been brave enough to traverse this place.\n\nI fear if something isn't done soon, there will be no caravans that will dare make the trek to Freewind Post.\n\nGo, slay as many of these harpies as you are able. Return to me once the deed has been done, and I will reward you well for your efforts.", objectives = "Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies." }
WordHunterWoW_QuestEN[98071] = { title = "Brewer's Trade", description = "Worked a bit o' a trade with the Dun Garok brew-kin. We're not the only ones missin' the vineyards of the Fallrook family, it seems! Most o' the best bottled years are long since drank, but we do have cases of the wine still in the cellars. \n\nBring this case of Fallrook Varietal to Dun Garok in the southeast and leave it with 'em by their gatherin' fireplace at the bottom of their fort.\n\nIn return, carry a sack o' the Homebrew Hops back with ye.\n\nThat keep is the closest thing to home around here!", objectives = "Deliver the bottles of Fallrook Varietal to Dun Garok in southeast Hillsbrad Foothills, and bring back a sack of their Homebrew Hops.", completion = "That's the hops smell I missed! Ye done me a great favor, {name}, takes me days to leave every time I make the trip to Dun Garok myself. Hard to pull me self outta the halls o' that fortress once I get comfortable.\n\nHappy to keep some old tastes on the shelf for fellow dwarves.\n\nHave a little somethin' for helpin out." }
WordHunterWoW_QuestEN[98072] = { title = "Crocs of the Sky", description = "You're quite the go-getter! I have just one more favor to ask, if you're up for something a bit more dangerous.\n\nThe crocolisk trade is steady money, but they're small fish compared to what whelp scales will bring. Folks will pay top dollar for a sack of those.\n\nCrocs of the sky, I call 'em! There's no way my apprentice could get them--but it seems right up your alley!\n\nYou'll find whelps far to the east, along the Green Belt. But be careful, there's nasty orcs in those hills!", objectives = "Collect 10 Pristine Crimson Scales and bring them to James Halloran in Menethil Harbor." }
WordHunterWoW_QuestEN[98093] = { title = "Field to Clear", description = "I'm so glad you saw me!\n\nThe weather was lovely this morning, so I walked from Camp Taurajo down the golden road. When it came time to head back, I couldn't--a pack of hyenas started circling, and Stormhide lizards blocked my only escape.\n\nScrambling up this tree I went, and now there are too many foes about at this hour for me to make the run home through the fields.\n\nWould you mind clearing out these Stormhide and Hecklefang Stalkers for me?", objectives = "Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely.", completion = "Thank you for helping me out, {name}. I'll let Camp Taurajo know you were able to rescue me. I'm so lucky you helped, I could have been stuck there all day!\n\nThis is all I have to spare, but I hope it's useful to you.\n\nI'll be making my exit once I make the careful climb down." }
WordHunterWoW_QuestEN[98094] = { title = "Scout Support", description = "Now that we can trust you to deliver critical information to our forward spies, there's an extra task for you.\n\nBring this to Deathstalker Masoj almost directly south of us. He'll have more for you to do once you get there and hand this to him. He is posted on elevated terrain north of the rotten vineyard they call Nethander Stead.\n\nOur plan to take control of these lands continues steadily.", objectives = "High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok", completion = "Quaint. A fresh face for the field work.\n\nWell, let's see what you have then." }
WordHunterWoW_QuestEN[98095] = { title = "Valuable Vantages", description = "Our high command inserts strategic troops using bat riders. Key points around the foothills have lost their signaling beacons.\n\nTake these vials. Uncork them in three locations: the hills bordering Dun Garok, the plataeu overlooking Dunholde Keep, and the last on the ridge of the Headland above the town of Hillsbrad. The vapors that emanate will be like a potent tuning rod to the senses of the bat, drawing them to the desired drop-off points once more.\n\nLook for crushed empty vials and renew our marks.", objectives = "Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him.", completion = "Good work. We advance the plans.\n\nDeathstalkers dare.\n\nLet purpose guide your strikes, {name}." }
WordHunterWoW_QuestEN[98155] = { title = "Pristine Pesterhide Pelts", description = "The Pesterhide hyenas of Thousand Needles have the most gorgeous coats. I haven't seen such a brilliant hue of fur like that in all of my travels!\n\nI would like to send back some pelts to my sisters back in Stormwind, as I know they could make something incredible out of them.\n\nI don't have any fighting experience, so I would be very grateful if you could gather some of the Pesterhide pelts in my stead.", objectives = "Bring 5 Pristine Pesterhide Pelts to Kristy Grant.", completion = "Thank you, {name}! These hides are in perfect condition. I can't imagine it was easy to get so many, but I am very grateful to you for your work." }
WordHunterWoW_QuestEN[98156] = { title = "Packaged Pristine Pelts", description = "{name}, you have been so helpful to me I hate to ask for yet another favor. It will be some time until I am able to return home to Stormwind. I was wondering if you would mind delivering these pelts to my sisters in my stead?\n\nI am sure you are more likely to return there before I am able to. Please deliver these pelts to my sisters Kelly and Kimberly in Stormwind. They can usually be found in the Park.", objectives = "Bring the Package of Pristine Pelts to Kimberly Grant.\n\nProvided item:", completion = "This is from our sister? We hadn't heard from her in some time. I hope she is doing well.\n\nMy, these pelts have such a beautiful color of fur! Kelly and I will make sure we put these to good use.\n\nThank you for making the long journey. It is good to know Kristy is still doing well and is thinking of us." }
WordHunterWoW_QuestEN[98189] = { title = "Return the Statuette", description = "My goodness, it's--it's beautiful!\n\nThe Blind Princess was to deliver this to Menethil Harbor before tragedy struck. We were so close!\n\nI believe it was to be signed for by Captain Stoutfist in Menethil Keep just behind us. Why don't you do the honors of finishing the job?", objectives = "Bring the Menethil Statuette to Captain Stoutfist in Menethil Keep.", progress = "What's that you've got there? Let me take a look.", completion = "You managed to get it back from those monsters! There aren't too many artifacts of the late king left now." }
WordHunterWoW_QuestEN[98190] = { title = "A Friend of the Family", description = "You'll want to take this to Stormwind right away. Proud as I am that this keep and harbor bears King Terenas Menethil II's name, we are a calm harbor in a very nasty storm of enemies. It's just not safe here.\n\nThe Dragonmaw in particular would sacrifice much to loot something like this... and I shudder to think of what they'd do with it.\n\nDon't bother going up the chain of command on this one, <lad/lass>. Go straight to Highlord Fordragon with this. He'll know where it will be best kept.", objectives = "Bring the Menethil Statuette to Highlord Bolvar Fordragon in Stormwind Keep.", progress = "Let us speak, {class}. I can feel you carry something of the Light.", completion = "You have my gratitude for recovering this. I am relieved it did not fall into the wrong hands." }
WordHunterWoW_QuestEN[98191] = { title = "A Friend of the Family", description = "King Terenas was a good man. A devout man. Beloved by his people, and truly the reason we have this Alliance at all.\n\nThe irony is he was humble--he hated these sorts of memorials, and so precious few exist. And of those, few survived Lordaeron's fall.\n\nIt seems the Light has coalesced in this statuette. It would be best kept in the Cathedral of the Light in Cathdral Square, in the center of the city. Bring it to Lord Grayson Shadowbreaker for safekeeping.", objectives = "Bring the Menethil Statuette to Lord Grayson Shadowbreaker in the Cathedral of Light.", progress = "Light be with you, {class}. You are clearly not here for small talk--what is it?", completion = "By the Light... it looks just like his boy...\n\n<Lord Grayson Shadowbreaker pauses for a moment.>\n\nThis statuette has indeed been blessed. Its connection to Terenas, its survival of what that monster did to him... this carries great power for those who believe in its strength.\n\nIt is best kept here for now, under guard of the paladin order. We will meditate on it further to learn more of its gifts, and perhaps it may aid us in dark times ahead.\n\nThank you, {class}. Light bless you." }
WordHunterWoW_QuestEN[98197] = { title = "Spoils of War", description = "This harbor was first built by the Old Horde as a staging ground for their naval invasion of Hillsbrad. Completely circumvented Lordaeron's defenses!\n\nSo many lives lost...\n\nWhat's worse is that fleet was built with the very resources they stole from Khaz Modan!\n\nPlenty of it remains in the harbor after Admiral Proudmoore routed the brutes and built this place for the Alliance. We'll need it to bolster the town's defenses with the Dragonmaw on the move.", objectives = "Recover 6 Khaz Modan Timber and 30 Khaz Modan Iron from Menethil Harbor for Valstag Ironjaw.", progress = "Keep your wits about you beneath the waves. There's plenty of nasties down there!", completion = "Ah! A bit damp, but nothing a few days in the sun won't fix.\n\nThank you, {class}. It's nice to not solely rely on shipments from Theramore or Auberdine for once!" }
WordHunterWoW_QuestEN[98208] = { title = "Bloom of the Heavens", description = "I came to Menethil Harbor from Auberdine, from the great tree Teldrassil, to recover a bloom of great import to my people.\n\nMy people's ship the Flying Osprey crashed here many moons ago, joined with the Kul Tiran Third Fleet. Among its cargo was the flower known as Nord'el--Bloom of the Heavens in your tongue--bloomed under a full moon at the peak of Mount Hyjal, our former home.\n\nPlease help me retrieve it! The wreckage is just south of the city, but it is inhabited by fierce murloc raiders!", objectives = "Recover Nord'el for Sylessa Duskwhisper in Menethil Harbor.", completion = "It has survived! Oh, Elune be praised!\n\nA thousand thanks, {name}. If you are willing, I do have one more favor to ask of you..." }
WordHunterWoW_QuestEN[98209] = { title = "Bloom of the Heavens", description = "Would you please deliver Nord'el to elder Thundris Windweaver in Auberdine?\n\nThe boat from here should be able to get you there swiftly.\n\nI apologize for the request, I truly do. I remain fatigued from my journey here--and from fleeing those murloc devils when I first attempted to retrieve the sacred bloom!", objectives = "Bring Nord'el to Thundris Windweaver in Auberdine in Darkshore.\n\nYou recall Sylessa mentioning a boat in Menethil Harbor can take you there." }
WordHunterWoW_QuestEN[98216] = { title = "Understanding Our Present", description = "Old Gods?! This cannot be good news at all!\n\nI've made out a new bit on the stone that speaks of a guardian of some kind. Whatever it is, it must be linked to the stone!\n\nTake it with you and see if you can find a big Titan construct of some sort in the excavation. Read this here final passage on the stone and see what happens!\n\nIf I'm right, you'll activate the thing. Take it out if so, but try to preserve anything interesting! We simply must know more!", objectives = "Use the Goaz Stone near the Goaz Warder and bring its Titanic Keystone back to Prospector Whelgar.", completion = "Look there--see how the Goaz Stone starts to glow when near the keystone? I can almost make out some more words...\n\nWe still must learn more about this Goaz. I feel like we're just on the tip of the iceberg with something huge!" }
WordHunterWoW_QuestEN[98219] = { title = "The Shamed Lieutenant", description = "Thank you again for delivering the statuette safely, {name}.\n\nI could use your help with something else. There's a member of the city guard who was reassigned to duty in Southshore out in the Hillsbrad Foothills.\n\nHis father was a friend of mine, and while I don't disagree that he could use the lesson... I'd still like to see him succeed. He would really benefit from someone like you helping him out.\n\nThere is a boat that can take you that way from Menethil Harbor, if you are passing back through.", objectives = "Speak to Lieutenant Farren Orinelle in Southshore in Hillsbrad Foothills.", completion = "Ah, of course. Another one of Stormwind's finest here to check on me. Same as last month!" }
WordHunterWoW_QuestEN[98221] = { title = "From the Ashes", description = "In the Second War the Dragonmaw built a fleet where we now stand, intending to take Hillsbrad. They nearly succeeded!\n\nThey were routed by the red dragons, left to mere stragglers deep in the mountains. However, there has been a surge in activity in their encampment northeast of Menethil.\n\nDun Algaz is proof that they intend to march to war once again and retake this land. Find their attack plans, take note of any critical information, and destroy them. We need to know where they will strike next!", objectives = "Captain Stoutfist in Menethil Keep wants you to destroy the 4 sets of Attack Plans in the Angerfang Encampment.", completion = "Ironforge as well? Nek'rosh certainly has his father's ambition!\n\nWhat he lacks, of course, is the enslaved army of red drakes that proved so devastating in the war. He's made a gambit, alright--one he will pay for dearly." }
WordHunterWoW_QuestEN[98223] = { title = "Old Habits", description = "This book has been badly burned--perhaps by the dragonfire that destroyed much of the Dragonmaw clan.\n\nOf what little is legible, it seems to describe rituals relating to the use of the Demon Soul that the clan had used to control the dragons.\n\nIt is far too incomplete to be of real use, but based on roughly inserted pages on animal hide it seems Nek'rosh had attempted to salvage it. Freshly dried ink mentions a \"Shadow Council.\"\n\nCaptain Stoutfist in Menethil Harbor would want to know about this.", objectives = "Bring the Tattered Spellbook to Captain Stoutfist in Menethil Harbor." }
WordHunterWoW_QuestEN[98230] = { title = "This Land Was Their Land", description = "After the War of the Three Hammers that tore dwarven life as we knew it apart, the Wildhammers settled here, founding the mountain fortress of Grim Batol.\n\nIt was a wondrous place. Gryphons soared everywhere you looked, diving down through the wetlands to grab a fish.\n\nIt didn't last long, sadly.\n\nHowin Kindfeather is one of the first Wildhammers to return in ages. Keeps to himself, far outside of town. Follow the road east--you'll find him eventually. He could surely use a hand.", objectives = "Find Howin Kindfeather east of Menethil Harbor, along the road." }
WordHunterWoW_QuestEN[98240] = { title = "Crimson Crate Delivery", description = "Word is officially out on those whelps, {name}. We already have an order in!\n\nI'll package 'em up all nice for you, then you take it out to the customer. I know, I know; it's just one last favor, I promise!\n\nThese will be for one \"Howin Kindfeather\". Sent his gryphon into town of all things with a letter for the order! Says he's just off the road to the east, a bit past Whelgar's Excavation Site, if you're familiar.", objectives = "Bring the Crimson Crate to Howin Kindfeather off the road to the east of Menethil Harbor." }
WordHunterWoW_QuestEN[98245] = { title = "Razormaw Needling", description = "I don't know who I hate more: the bloody Dark Irons, the Dragonmaw, or the drakes they rode.\n\n<Howin spits.>\n\nI aim tae make things right. But we're gonna need some supplies.\n\nThese whelp scales will protect against dragonfire a good bit, but they're a pain in the arse tae weave together.\n\nThe Razormaw raptors up in Raptor Ridge to the northeast and Saltspray Glen to the northwest are so named for their pointy chompers--they oughta break through the scales.\n\nBring me a handful of the incisors.", objectives = "Collect 10 Razormaw Incisors for Howin Kindfeather." }
WordHunterWoW_QuestEN[98246] = { title = "Trying Times", description = "I'll need some eggs if my plan is going tae work. Bassbeak needs a nice an' full belly--I ain't in the business of hoppin' on the back of a surly gryphon.\n\nThey need to be perfect--no cracks or anything.\n\nTake some from the Razormaw raptors--they're known for having yolks the size of a gnome's noggin. You can find 'em in Raptor Ridge to the northeast and Saltspray Glen to the northwest.\n\nLet's make it a nice even dozen, just to be safe.", objectives = "Gather 12 Perfect Razormaw Eggs for Howin Kindfeather." }
WordHunterWoW_QuestEN[98247] = { title = "Shipping Label", description = "<A torn shipping label can be found on the side of the now fully stocked crate. Though the intended recipient is torn off, details of its origin still remain.\n\n\"Property of the Azeroth Commerce Authority. Please return empty crates or unfulfilled shipments to our local trade hub at the Three Corners crossroads in Redridge Mountains. Couriers will be compensated for their time and travel.\"\n\nBeside the text is a crudely drawn map of the area near the aforementioned destination.>", objectives = "Deliver the Shipping Label to someone at the Azeroth Commerce Authority trade hub in Redridge Mountains.", progress = "Ah, greetings! How can I be of assistance?", completion = "You have arrived at the right place! I am happy to mark you down as one of our affiliates. No contracts to sign and no commitments to weigh you down. All we ask of you is your diligence to assist in completing or returning any of our deliveries you find on your travels.\n\nWhen you do so, you will be compensated with Merchant's Favor that will allow you to purchase goods and services we offer here. In fact, here's a little bit to get you started.\n\nNow, do you happen to have the crate this came from?" }
WordHunterWoW_QuestEN[98248] = { title = "Shipping Label", description = "<A torn shipping label can be found on the side of the now fully stocked crate. Though the intended recipient is torn off, details of its origin still remain.\n\n\"Return damaged shipments or empty crates to the Durotar Supply and Logistics trade outpost, now conveniently located due west of the Crossroads in the Barrens. Your time is valuable and we will compensate you for your efforts!\"\n\nBeside the text is a crudely drawn map of the area near the aforementioned destination.>", objectives = "Deliver the Shipping Label to someone at the Durotar Supply and Logistics trade hub near the Crossroads in the Barrens.", progress = "Good day, traveler. How can I assist?", completion = "You found the right place, and you're speaking with the right person! I can jot you down as one of our new associates. No paperwork necessary on your part, I can't be bothered with more of that.\n\nAll we ask of you is to assist in dealing with compromised deliveries you find out during your travels. Doing so will earn you Merchant's Favor, which you can use to purchase goods and services right here. Here's a bit to get you settled in!\n\nDo you happen to have the crate this label came with?" }
WordHunterWoW_QuestEN[98251] = { title = "Never Coming Back", description = "Gaaah!\n\nI'm so angry. They said Ashenvale was easy to follow. Easy for who? The beasts? The birds?\n\nOne moment I was gathering an herb, the next I'm trapped in this ravine. Do I truly have to circle half the forest to reach where I stood just moments ago?\n\nWhen I'm like this, my spells grow volatile and behave... differently.\n\nCould you thin the wildlife nearby? Even their stupid hooves grate on me. I despise this cursed forest.", objectives = "Kill 6 Shadowhorn Stag and 6 Ashenvale Bear and return to Va'xug Firefure northwest of Fallen Sky Lake.", completion = "Ha! That's right, you beasts!\n\nThanks. That does seem to already have helped." }
WordHunterWoW_QuestEN[98252] = { title = "A Void Path", description = "Show my Eye of Kilrogg the way out of this ravine and back to the Ashenvale road. Keep it moving and I'll follow once I see a clear path.\n\nI'll stay here--one of us should keep our bearings. If you lose the way, I can guide you back through the eye. I will not have us both wandering blind in this malicious forest.\n\nI can hold the channel for four minutes. No longer. Reach the road before the vision breaks, or return to me and we try again.", objectives = "Show Va'xug's Eye of Kilrogg the way back to the main Ashenvale road." }
WordHunterWoW_QuestEN[98282] = { title = "Alchemical Hazards", description = "Certain alchemical recipes require ingredients sourced from, well, very dangerous places. And those are often just the base herbs! The other ingredients are even worse!\n\nI need to make more antivenom before I can leave again. I swear everything in this marsh is venomous. It's like it runs through the land itself!\n\nCan you help me? I'll need a venom gland from the spiders in Thelgen Rock to the far southeast. But it has to be unruptured, or too much venom will spill out before you can get here. Sorry!", objectives = "Collect an Unruptured Stalker Gland from Thelgen Rock for Caitlin Grassman in Menethil Harbor.", progress = "Have you had any luck? I know it's a pain to ask, but I really do need a whole gland!", completion = "Oh, perfect! This is exactly what I need. You're a real hero, you know.\n\nPlease, I'd be remiss if I didn't share some of the fruits of your labors with you. Stay safe out there!" }
WordHunterWoW_QuestEN[98283] = { title = "Carnage", description = "The natural order of this land is breaking. Once it was that the Razormaw raptors kept the land from overgrowth. They now live in fear of their alpha, named only for the carnage it leaves behind.\n\nI fear the beast has been driven mad by the sickness that we have yet to fully excise.\n\nIt will respond to the malignant flesh of the diseased bears below Raptor Ridge, to the northeast. Leave their entrails in its cave lair.\n\nCarnage will come. Bring me its head.", objectives = "Bring Carnage's Head to Rethiel the Greenwarden in The Green Belt." }
WordHunterWoW_QuestEN[98284] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Enchanted Lute. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[98285] = { title = "Camping 101: Engineering", description = "An engineer is ever-resourceful, and if you are in the wilds alone, it's always good to be able to put your trade to use. No good camp is complete without a few helpful constructs!\n\nYes, come back and see me when you've gained a little bit of experience as an engineer and I can show you how to make something special!", objectives = "Speak with the Strange Hermit in Shadowgale Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Reagent Bot. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[98286] = { title = "Camping 101: Enchanting", description = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", objectives = "Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Enchanted Lute. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics." }
WordHunterWoW_QuestEN[98287] = { title = "Camping 101: Engineering", description = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells.", objectives = "Speak with Sprite Jumpsprocket in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill." }
WordHunterWoW_QuestEN[98291] = { title = "Death to the Dragonmaw", description = "I plan tae get back into Grim Batol and reclaim it for the Wildhammers, {name}. Or at least learn a thing or two.\n\nDon't look at me like that, now. I know the risks. I don't intend tae go in hammer swingin', ye know.\n\nRegardless, I'll need your help first. The Dragonmaw orcs march as we speak. They're all up an' down the Dragonmaw Retreat, where the red dragons routed them before.\n\nI need you tae thin their numbers before I have any chance of gettin' close. Ye can't miss 'em if you follow the road east.", objectives = "Kill 8 Dragonmaw Reclaimers, 5 Dragonmaw Soulbinders, and 3 Dragonmaw Infiltrators in Dragonmaw Retreat for Howin Kindfeather." }
WordHunterWoW_QuestEN[98293] = { title = "Forced Disarmament", description = "The Dragonmaw are stockpiling all manner of weaponry. It would be wise to relieve them of these before more soldiers can be armed.\n\nCaptain Stoutfist in Menethil Keep would surely be interested in these.", objectives = "Collect 30 Dragonmaw Armaments in Dragonmaw Retreat, then bring them to Captain Stoutfist in Menethil Keep." }
WordHunterWoW_QuestEN[98297] = { title = "Stopping the Cycle", description = "I did a quick test flight while ye were out. The good news is the armor ye helped me craft for Bassbeak works like a charm!\n\nThe very bad news is I saw a group o' them Dragonmaw in the process of enslavin' a red dragonspawn.\n\nAbsolutely not. Not again.\n\nYou have tae take it out. You'll certainly need friends tae do so. Kill the warlocks holding it down first--that ought tae free it. Then put it out of its misery.\n\nNone of them will stand in the way of the Wildhammer.", objectives = "Kill the Subdued Dragonspawn at the Dragonmaw Gates for Howin Kindfeather." }
WordHunterWoW_QuestEN[98298] = { title = "Arugal's Folly", description = "Ah, it's all become so embarrassingly clear! Arugal hardly had any magic at all, let alone enough to create the worgen. 'Arugal's Curse.' Pah! Barely potent enough to last a few seconds.\n\nThese shackles prove he can bind the beasts, not create them. The worgen clearly spread their curse a different way. I would know how.\n\nGo to the Greymane Wall to the south. The worgen seem to be spreading to the humans nearby. Tear the beasts apart and bring me whatever you find. This requires a more direct approach.", objectives = "Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.", progress = "Fangs, claws, gizzards. It makes no difference to me. The easiest way to study something is to see the guts yourself.", completion = "It appears I get the last laugh after all, haha! Arugal truly was a fool. And I, Dalar Dawnweaver, have exposed him as the fraud he is.\n\nThese pieces are all the proof I need that the curse has nothing to do with that blithering dolt.\n\nRegrettably, that means his remedy is also worth nothing. It seems the search for a solution to the worgen curse continues." }
WordHunterWoW_QuestEN[98299] = { title = "Stop the Spread", description = "If there is one thing we do know, it is that Arugal is responsible for worgen within Silverpine--be it his own machinations or otherwise. What we don't know is how it spreads.\n\nWhile I research a way to stop the curse, our first priority is to contain it. It appears this affliction cannot infect forsaken, but a large group of humans have gathered by the Greymane Wall.\n\nGo to the wall and put down these refugees before they have a chance to become servants for Arugal. And try not to get bit, {race}.", objectives = "Slay 5 Sickly Refugees and 5 Haggard Refugees for Dalar Dawnweaver in The Sepulcher.", completion = "It seems the Gilneans are not too keen on allowing anyone past their wall. That is fortunate, I suppose. It means there is likely no chance for the worgen curse to spread to their city.\n\nCan you imagine the depravity if an entire kingdom were infected?" }
WordHunterWoW_QuestEN[98300] = { title = "Word to Ironforge", description = "My work here is far from over, {name}. And I need tae send word to me wife Claira in Aerie Peak--and get Falstad an update as well.\n\nBut that's my business. Wildhammer business.\n\nThat said, you ought tae let King Magni Bronzebeard in Ironforge know about all this as well. Wetlands is but a stone's throw from his lands, and none of what's happenin' here is good news on one's doorstep. This letter oughta do the trick.\n\nYe can travel back through Dun Algaz or fly from Menethil Harbor to get to Ironforge.", objectives = "Deliver Howin's Missive to King Magni Bronzebeard in Ironforge." }
WordHunterWoW_QuestEN[98310] = { title = "Gleaning Our Future", description = "There are other, larger golems all around the Wetlands. They each bear inscriptions marking them as Ados, Modr, Golm, and Neru--matching the missing pieces of the Goaz Stone you found!\n\nI'd be willing to bet if we can bring pieces of them as well, we'll reveal more of the Goaz Stone!\n\nYou'll find Ados at the Dragonmaw Gates to the east, near Grim Batol. Modr is right outside Dun Modr to the north. Golm lies beneath Grim Batol, east of Dun Algaz. Neru's behind Direforge Hill, to the northeast.", objectives = "Use the Goaz Stone near Ados, Modr, Golm, and Neru and bring their hearts back to Prospector Whelgar." }
WordHunterWoW_QuestEN[98313] = { title = "For Further Study", description = "Whatever this is all about, {name}, it's epic stuff alright.\n\nI'll bundle everything up nice for you. Take it to Historian Karnik in the Hall of Explorers in Ironforge. You'll usually find him in the back, nose-deep in some tome or another in the library.\n\nIt'll take a downright army to crack the case on this one, but if what we've seen so far is any indication it will well be worth it!", objectives = "Bring the Whelgar Relic Package to Historian Karnik in Ironforge." }
WordHunterWoW_QuestEN[98319] = { title = "Secure the Mountain", description = "It's bad enough havin' a troll problem, but the mountains are filled tae the brim with wendigos! They normally keep to their own caves, but they seem tae be spreadin' like bunnies. Now they've filled the Grizzled Den north of here.\n\nIf we want Whitebeard's report, we're gonna need to find my partner Cornelius. The blockhead got a little too excited and charged in head first. Brave, but stupid.\n\nHead into the cave and see where he is. And feel free to take out some of the beasts while yer at it.", objectives = "Find Mountaineer Cornelius in the Grizzled Den for Mountaineer Gretchen.", completion = "Ach, the fool...\n\nThank ye for the help, {name}. Guess we have our report." }
WordHunterWoW_QuestEN[98321] = { title = "Flintfire's Shipment", description = "Hoha! Good to see a {race} who's not afraid to get their hands dirty.\n\nIf yer lookin' fer work, I'm afraid I'm a little short on supplies at the moment. Our most reliable source of ore has been overrun by wendigo and now the cave has been abandoned. The miners had to drop everything when they fled!\n\nSay, why don't ye poke yer head around the Grizzled Den to the west and see if you can find some of our missing shipments. It would save us a great deal o' trouble.", objectives = "Collect 8 Flintfire Shipments from the Grizzled Den for Tongus Flintfire in Kharanos.", progress = "Wendigos are nasty beasties. Its just good all the miners made it out of the Grizzled Den in one piece!", completion = "Now that's more like it! With these shipments we'll get the forge back up and runnin' in no time!" }
WordHunterWoW_QuestEN[98322] = { title = "Secure the Mountain", description = "Spelunking dark caves is adventurer business. My job's just to make reports and send them over to Ironforge.\n\nTrouble is, one of my reports hasn't... well, reported back. I asked a few mountaineers to learn more about the wendigo problem we have out here, but I haven't heard from them.\n\nIf you're already going to be out and about, what say you check in with Mountaineer Gretchen just west of town. I'm late enough as it is!", objectives = "Check in on Mountaineer Gretchen west of Kharanos.", completion = "Ol' Whitebeard sent ya, aye?\n\nI got his report, alright. This whole situation's a mess!" }
WordHunterWoW_QuestEN[98323] = { title = "Secure the Mountain", description = "Hopefully ye put down a fair number of the mongrels while you were in there. Shame about Cornelius, though.\n\nFrom what you described, there's not much to report other than the cave is a lost cause. Whitebeard's not gonna like that answer, but I'm not darin' sendin' anybody else into that death trap.\n\nFeel free tae pass along the message, {name}. I'm not leavin' this spot till the mountain's secure.", objectives = "Deliver Mountaineer Gretchen's Report back to Senir Whitebeard in Kharanos.", progress = "Ah, you're back just in time.\n\nWhat's the matter, lad? You look like you've seen a ghost.", completion = "Completely overrun? Why am I not surprised.\n\nWell, that's going in the report too.\n\n<Senir folds Gretchen's letter into his pile of notes>" }
WordHunterWoW_QuestEN[98326] = { title = "Frosthowl", description = "Do ye know how hard it is to fish on a frozen lake? My poor husband, Paxton, has been out in the middle of it for days and we barely have a single sack to show fer it.\n\nWell, we DID have a sack to show fer it. Until the thrice-damned wendigo attacked me and made off with our haul. It'll take us weeks to fish all that back up! If that loudmouth Frosthowl didn't scare 'em all off, anyway.\n\nDo us a favor and get it back, aye? Drooling brute is hiding somewhere deep in the Grizzled Den to the southeast.", objectives = "Slay Frosthowl and collect the Sack of Fish for Gretta Ganter in Brewnall Village.", progress = "It'll be a hot day in Dun Morogh before I tell Paxton I lost his entire stockpile to a wendigo.", completion = "Yer a real lifesaver, {name}!\n\nMy husband would just laugh it off, but I couldn't bare tellin' him he has to spend another night on the lake. Maybe now we can enjoy a real feast." }
WordHunterWoW_QuestEN[98338] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[98340] = { title = "The Great Cat Spirit", description = "It would seem that you are ready for the next step in your journey, young druid. Dendrite Starblaze has sent for you, and wishes for you to seek him out in Moonglade once again.\n\nYou have already learned to call upon the magic to take you to Moonglade, so you should be able to embark immediately if you choose. I would suggest you leave soon, if you wish to continue your druidic training.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", completion = "And so it continues, Father Cenarius.\n\n<Dendrite makes a quick, invisible gesture in the air above him. A slight aura of power falls over him.>\n\nGreetings again, {name}. It is time for you to learn the next perspective of nature: the cat. I will put you on the path to understanding this aspect of druidic life, but much like the bear, it is you that must embrace this learning and propagate it." }
WordHunterWoW_QuestEN[98341] = { title = "The Great Windborne Cat Spirit", description = "A spirit of your homeland has recently appeared here and has asked me to guide you to it. This windborne cat spirit has come to tutor and mentor you so that you may take the feline shape of the spirit on Zephras.\n\nAll druids eventually seek this wisdom, though it seems your homeland has a slightly different shape than our traditional one. If you desire to take this spirit's feline form, you will need to undergo our trial.\n\nIt can be found in the southern part of Moonglade, south of the twin bridges.", objectives = "Seek out the Avatar of Saeyleenan in southern part Moonglade and learn what it has to share with you about the nature of the windborne cat.", completion = "Greetings, young shen'dorei. I have come to you because I sense you are ready to undertake the trial to determine if you understand my spiritual nature or not.\n\nI will have you take the trial of the Great Cat Spirit of Azeroth, but as you are from Zephras, I wished to oversee your progress myself. After all, it is my shape you would take, not that of a Azerothian cat spirit.\n\nLet us begin." }
WordHunterWoW_QuestEN[98342] = { title = "The Great Cat Spirit", description = "To draw upon my spirit, you will need more than a few words. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics of my favor you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me. We will see if you are ready to take my shape.", objectives = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit.", progress = "Ah, you have returned. I do hope you have brought the relics with you?", completion = "Excellent. You have shown you understand the true nature of the cat, and are able to embody the cunning, stealth, and ferocity needed to take my shape.\n\nI now deem you worthy of my blessing, young {class}." }
WordHunterWoW_QuestEN[98362] = { title = "To Thunder Bluff", description = "The time has come for us to part ways once again, young one, as the application of your lessons takes you back to whom that sent you to me. It would seem your instructor, Turak Runetotem, has found a worthy pupil in you. I believe I see one as well. Heed his lessons and you shall soon be able to draw upon the Great Cat Spirit to take its shape.\n\nGo back to whence you came. When the time is right, we will meet again.", objectives = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.", completion = "Welcome back, {name}. I can sense you have met with the Great Cat Spirit and have successfully completed the trial. All druids must pass a trial given by this spirit, though the trials vary by generation. I am proud you have passed and have heeded the wisdom of the Great Cat Spirit. It is an ancient spirit that is as deadly as it is playful, though I can sense you understand the spirit's nature already.\n\nI will now instruct you on how to take the shape of the cat." }
WordHunterWoW_QuestEN[98372] = { title = "An Unfortunate End", description = "", objectives = "The deceased Night Watchman lying before you is covered in deep gashes and cuts. It's clear to see that he was mauled by some sort of large beast.\n\nYou notice that the corpse has an unlit torch in his hand. You reach down and pry it from his stiff fingers. This could be useful in your travels through Duskwood and beyond to reveal things hidden by darkness.", completion = "The deceased Night Watchman lying before you is covered in deep gashes and cuts. It's clear to see that he was mauled by some sort of large beast.\n\nYou notice that the corpse has an unlit torch in his hand. You reach down and pry it from his stiff fingers. This could be useful in your travels through Duskwood and beyond to reveal things hidden by darkness." }
WordHunterWoW_QuestEN[98386] = { title = "Alther's Mill", description = "Orcs, gnolls, murlocs. Everything seems to be out to stop me from getting this bridge done on time. Now we have word there's an infestation of tarantulas at our lumber mill!\n\nIf you're up to earn a bit more coin, would you head over to Alther's Mill to the east and clear out their spider problem? Place is as good as useless to me if I can't safely send workers to collect shipments.\n\nOh, and if you see ol' Alther, tell him he owes me for cleaning up his mess.", objectives = "Slay 12 Greater Tarantulas and destroy 6 Tarantula Eggs in Alther's Mill for Foreman Oslow in Redridge.", completion = "The mill is that bad? That's worse than I thought.\n\nI'm not particularly squeamish, but work's bad enough without spiders snatching up my workers. Thanks for the help,{name}!" }
WordHunterWoW_QuestEN[98387] = { title = "Blackrock Blockade", description = "What the Blackrock orcs don't understand is that this is a war of attrition. Their brazen push into Alliance territory has left them vulnerable and without supplies, relying on the surrounding mountains to gather resources.\n\nAn army can't run on empty bellies, {name}. Go to their encampments south of Stonewatch Keep to the east and rob them of their food and weapons. Let's see the orcs' fighting spirit when they're starved and defenseless.", objectives = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", progress = "Most of what you find will have been raided from Lakeshire anyway. It will do me good to know our people will thrive while the orcs wither.", completion = "Excellent work, {name}. With the Blackrock orcs cut off from their allies in the Burning Steppes, they will have no hope of maintaining their foothold here without proper supplies." }
WordHunterWoW_QuestEN[98389] = { title = "A Light in the Darkness", description = "Greetings, {class}. Yes, I am a paladin. Not even death can stop the Light.\n\nThis my kind have in common with all Forsaken--we have overcome what the living view as their end. However, some even among our own fear us; they suspect we will smite them as some monstrosity.\n\nIn truth, our relationship with undeath is complex, but I am not here to hurt our own. Help me show the others this. Venture to Night's Web Hollow to the northwest and free the freshly raised fools trapped by the spiders there.", objectives = "Free 6 Webbed Victims in Night's Web Hollow for Aramis Hammerhand in Deathknell.", progress = "Have you freed the poor, unfortunate souls trapped in that cave?", completion = "May this help Executor Arren and so many others see our true nature. Much like in our past lives, we live to serve our people--to protect them with the gifts the Light provides us.\n\nThey will see in time that we are just as valuable to the Dark Lady's plans as any other.\n\nLight be with you." }
WordHunterWoW_QuestEN[98391] = { title = "The Sisterhood of Elune", description = "Blessings to you, {class}. The Sisterhood of Elune has stood as a pillar of kaldorei society for thousands of years.\n\nBefore the Great Sundering, before the War of the Ancients, through the Long Vigil, we have guided and healed our people through the darkness. Such is our charge, and such is the demand of the peerless Mother Moon.\n\nWe now require your aid in a matter of great importance. Sister Aquinne awaits your arrival in Darnassus.", objectives = "Speak to Sister Aquinne in Darnassus.", completion = "I am glad you arrived so quickly. The Sisterhood requires your aid." }
WordHunterWoW_QuestEN[98392] = { title = "Darkness in the Glade", description = "These belts... look closely at the leather, {name}. Do you see the taint running through the fibers?\n\nI have a suspicion as to its origin, but we will need further proof to be sure.\n\nVenture back out into the harpies' nests to the west and take out their leaders. If their necklaces carry the same darkness as these belts, we'll have our answer.", objectives = "Collect Hatescreech's Amulet, Windmistress Gaedress' Amulet, and Witchmother Arysa's Amulet for Sentinel Arynia Cloudsbreak in the Oracle Glade.", progress = "Have you wrested the amulets from the harpies' leaders?", completion = "<Arynia investigates the amulets.>\n\nDo you see the foul green swirls within the gems? This is indeed fel moss corruption at work.\n\nI have heard similar reports from Shadowglen and elsewhere in the boughs of this substance turning our very world against us.\n\nI will inform my superiors of this at once." }
WordHunterWoW_QuestEN[98393] = { title = "The Great Cat Spirit", description = "It would seem that you are ready for the next step in your journey, young druid. Dendrite Starblaze has sent for you, and wishes for you to seek him out in Moonglade once again.\n\nYou have already learned to call upon the magic to take you to Moonglade, so you should be able to embark immediately if you choose. I would suggest you leave soon, if you wish to continue your druidic training.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", completion = "And so it continues, Father Cenarius.\n\n<Dendrite makes a quick, invisible gesture in the air above him. A slight aura of power falls over him.>\n\nGreetings again, {name}. It is time for you to learn the next perspective of nature: the cat. I will put you on the path to understanding this aspect of druidic life, but much like the bear, it is you that must embrace this learning and propagate it." }
WordHunterWoW_QuestEN[98394] = { title = "The Great Cat Spirit", description = "In the southern part of Moonglade, on a hill overlooking the bridge, resides a wise and cunning being we call the Great Cat Spirit.\n\nMuch like the Great Bear Spirit, this spirit has served as a tutor and mentor to druids that desire to take the feline shape. All druids eventually seek its wisdom, and if you desire to take the form of a cat, you will as well.\n\nGo meet with the Great Cat Spirit and learn what it will teach you.", objectives = "Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat.", completion = "I see you have come to learn to draw upon my spirit. Good. Let us see if you are ready to take my shape." }
WordHunterWoW_QuestEN[98396] = { title = "The Great Cat Spirit", description = "To draw upon my spirit, you will need more than a few words. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics of my favor you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me. We will see if you are ready to take my shape.", objectives = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit.", progress = "Ah, you have returned. I do hope you have brought the relics with you?", completion = "Excellent. You have shown you understand the true nature of the cat, and are able to embody the cunning, stealth, and ferocity needed to take my shape.\n\nI now deem you worthy of my blessing, young {class}." }
WordHunterWoW_QuestEN[98397] = { title = "To Darnassus", description = "The time has come for us to part ways once again, young one, as the application of your lessons takes you back to whom that sent you to me. It would seem your instructor, Mathrengyl Bearwalker, has found a worthy pupil in you. I believe I see one as well. Heed his lessons and you shall soon be able to draw upon the Great Cat Spirit to take its shape.\n\nGo back to whence you came. When the time is right, we will meet again.", objectives = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.", completion = "Welcome back, {name}. I can sense you have met with the Great Cat Spirit and have successfully completed the trial. All druids must pass a trial given by this spirit, though the trials vary by generation. I am proud you have passed and have heeded the wisdom of the Great Cat Spirit. It is an ancient spirit that is as deadly as it is playful, though I can sense you understand the spirit's nature already.\n\nI will now instruct you on how to take the shape of the cat." }
WordHunterWoW_QuestEN[98398] = { title = "The Oracle Tree", description = "I am impressed by what you have accomplished here in so short a time, {name}. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.\n\nI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.", objectives = "Find the Oracle Tree Bark nearby to receive its message.", completion = "As you inspect the fallen bark, a voice enters your mind. It is calm and soothing, cresting over you like a gentle breeze through the leaves." }
WordHunterWoW_QuestEN[98403] = { title = "Twisted Hatred", description = "Lord Melenas did not act alone; he was at the behest of another. The one you seek is Xethorr the Wicked. It seems he has twisted the spiders that call Teldrassil home, intending their venom for some foul plan.\n\nHe has taken residence deep in the forest, in the area to the northwest of here known as the Cleft. Take caution, and bring allies, for Xethorr is not an opponent to be trifled with.\n\nDispatch his brood, and bring me anything that may tell us more of the satyr's work here.", objectives = "Kill 8 Befouled Webwoods and bring Xethorr the Wicked's Mature Fel Moss to Tallonkai Swiftroot in Dolanaar.", progress = "<Tallonkai lowers his voice.>\n\nDoes Xethorr still walk freely?", completion = "I should have known this was being used to twist the spiders of this land.\n\nI have heard whispers of this substance being the source of much of the corruption plaguing us. Though this is not the original, it is an older sample and may yield more information than what we have obtained so far.\n\nNormally I would have you send this to Darnassus for further study. However, it is best we kept this quiet for the moment, or Dolanaar will never recover its reputation.\n\nI trust you to do the same." }
WordHunterWoW_QuestEN[98404] = { title = "The Great Windborne Cat Spirit", description = "In order to draw upon my spirit, you will need to undergo a trail. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me to pass the druidic trial of these lands.", objectives = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan.", progress = "Ah, you have returned. I do hope you have brought the relics with you?", completion = "Excellent. You have shown you understand the true nature of the cat, and are able to embody the cunning, stealth, and ferocity needed to take my shape.\n\nI now deem you worthy of my blessing, young {class}." }
WordHunterWoW_QuestEN[98405] = { title = "The Great Cat Spirit", description = "In the southern part of Moonglade, on a hill overlooking the bridge, resides a wise and cunning being we call the Great Cat Spirit.\n\nMuch like the Great Bear Spirit, this spirit has served as a tutor and mentor to druids that desire to take the feline shape. All druids eventually seek its wisdom, and if you desire to take the form of a cat, you will as well.\n\nGo meet with the Great Cat Spirit and learn what it will teach you.", objectives = "Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat.", completion = "I see you have come to learn to draw upon my spirit. Good. Let us see if you are ready to take my shape." }
WordHunterWoW_QuestEN[98407] = { title = "Show of Force", description = "If the gnolls are growing so bold they are willing to camp this close to humans, there's no telling how much further they'll go. We need to deter them.\n\nThe beasts are hardly organized, but they seem to respect strength above all else. If we can slay the worst of them, maybe claim some of their trophies, we can remind these gnolls why they should stay in the hills where they belong.\n\nShould you see any of their thrashers, bring me their collars. That should put the fear of the Alliance back into them.", objectives = "Collect 5 Spiked Collars from Gnoll Thrashers for Deputy Feldon near Lakeshire.", progress = "A full assessment of the gnolls cannot be complete without facing the worst of their kind. Put those thrashers down!", completion = "Quite the armful you have.\n\nWhile this doesn't solve our problem out here, I can rest comfortably knowing we've discouraged them pushing any further. Great work, {name}." }
WordHunterWoW_QuestEN[98417] = { title = "Vengeful Trail", description = "At the moment our fates bound us most vulnerable, tragedy fell upon our villages. Satyrs defiled our temples, their profane touch staining sacred boughs, and they slaughtered the innocent without mercy.\n\nKurothel was consumed by wrath. The druids are taking the fight to the satyr, and he has followed.\n\nOur bond endures. I feel my husband, west, within these woods. Please, return to me with news of his fate.", objectives = "Maseara Autumnmoon wants you to search west of Forest Song, amongst the Satyrnaar demons. Report any signs of her husband Kurothel upon your return.", completion = "Oh no... words like these do not bring me comfort. Kurothel must be more than living in the wild, he's living more like a wild beast each passing night.\n\nI fear the whispers must be true." }
WordHunterWoW_QuestEN[98418] = { title = "Shared Fury", description = "Kurothel mentioned sightings of what they say are wolf-men. Those of the pack now lurking in greater numbers in our forest. Last we had spoken, druids were pursuing communication with those of the beast heart who displayed measured control of their animal instincts.\n\nHis written words show a darker struggle. If there is anything we can do to help see HIM again, surely quelling the demon threat that is driving him to this burning transformation will be of aid to his anguished soul.\n\nSlay the Xavian, {name}.", objectives = "Kill 5 Xavian Rogues, 5 Felsworn, 5 Betrayers, and 5 Hellcallers.\nReturn to Maseara Autumnmoon in Forest Song afterwards.", completion = "There was a welling up of... Elune's light within and around me. I feel Kurothel has witnessed your act of battle within this war that rages within our land, and within our hearts.\n\nMy hopes are that with time, the efforts of our Sentinels and our wayward druids will eliminate the demonic menace once and for all. Perhaps then and only then will the feral drive for vengeance burn out from our lineage's heritage.\n\nThank you, {name}. You are an ally to the forest, and a friend of the Kaldorei." }
WordHunterWoW_QuestEN[98423] = { title = "The Treaty of Understanding", description = "Inside of the vault you find a tablet detailing the terms of a peace treaty between the Bronzebeard and Wildhammer dwarf clans. It appears to date back to the time period just after the War of the Three Hammers, and is very likely a notable piece of dwarven history. The king of Ironforge would no doubt be interested in this artifact.", objectives = "Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge.", progress = "What have you brought from the depths, {class}.", completion = "Ah yes, my ancestor Madoran was the first Bronzebeard king of Ironforge following the great civil war between the Wildhammer, Bronzebeard, and Dark Iron clans. This treaty was drafted to codify the cessation of hostilities and terms of peace after the Bronzebeards won the mountain.\n\nAs you can see, the Wildhammers and Bronzebeards signed it... and the Dark Irons did not.\n\nThank you for recovering this and bringing it to me, {class}." }
WordHunterWoW_QuestEN[98424] = { title = "Fizsprocket's Notes", description = "Some particularly worn papers are held separately, folded in Fizsprocket's inside breast pocket.\n\nThey seem to detail important information that could be used against the Venture Co. and its operations in the region. It would be prudent to look for more before returning to Morin Cloudstalker.", objectives = "Collect the rest of Supervisor Fizsprocket's pages inside The Venture Co. Mine and bring them to Morin Cloudstalker near Bloodhoof Village.", progress = "What is it you bring me, {class}?", completion = "Ah, this is most valuable knowledge. I thank you for your efforts.\n\n<Morin looks through the notes.>\n\nIt seems our next move is clear." }
WordHunterWoW_QuestEN[98427] = { title = "Ceasing Operations", description = "The shredder one of the pages speaks of--I have seen them before in my travels. They can decimate a forest in a fraction of the time that hand and axe can.\n\nEntire glades--homes to the Earth Mother's children for millennia--erased in days.\n\nWe will not allow this to happen in our home, a stone's throw from where our young ones take their first steps.\n\n{name}, I must ask you to gather others, go back into the mine to the northeast, and ensure it fells not a single tree more.", objectives = "Bring the Clearcutter Key to Morin Cloudstalker outside Bloodhoof Village.", progress = "Has the shredder been stopped, {name}?", completion = "All of Bloodhoof Village is in your debt this day. May the Earth Mother's grace stay with you always." }
WordHunterWoW_QuestEN[98430] = { title = "The Longwalkers", description = "Hail, {class}. What brings you deep into such a dark and violent place?\n\nI was sent here by High Chieftain Cairne Bloodhoof as a part of our efforts to communicate with the gnolls that have taken residence. The rest of my mission must remain a secret, as do all things with the Longwalkers, the trusted scouts of our chieftain.\n\nAll you must know is our diplomacy was met with violence, and I fear I may be tonight's feast for the gnolls if you do not help me escape.\n\nAre you up to the task?", objectives = "Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff.", completion = "I am relieved that Longwalker Stormhoof is well. He is my most trusted scout, and his mission of the utmost importance.\n\nPlease, accept my thanks and my hospitality for riskng your life to save his own. You have done a greater service to our people than you know.\n\nI encourage you to explore our great city while you are here. It is a place of safety, and you will find many that may aid you on your own travels upon its bluffs.\n\nIsh-ne-alo por-ah." }
WordHunterWoW_QuestEN[98435] = { title = "Thunderhorn's Report", description = "Our elders in Thunder Bluff must know of the progress we have made here, thanks to your aid.\n\nPlease, take this to Arch Druid Hamuul Runetotem in Thunder Bluff. You will find him in the Elder Rise, on the east side of the city. You must take the lifts up to the center of the city, then cross the bridges to reach it.", objectives = "Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff.", completion = "Ah, no wonder there is such joy running through the streams of Mulgore. You have done a great service today. The wells provide much for not only our people, but to the wildlife we depend on for food, clothing, and companionship.\n\nIt is my humble pleasure to honor Mull's request. Please, accept this token of my gratitude." }
WordHunterWoW_QuestEN[98447] = { title = "The Valor Family", description = "Despite you putting down the Valor family ghosts, the reports of attacks have not ceased. It was a good gamble, but perhaps we did not settle their unfinished business after all.\n\nFrom my research, it sounds like this family all went missing at the same time. Whatever trauma caused their spirits to be chained to this realm must have happened all at once.\n\nOur only clue is where you found the book. Return to Raven Hill and see what you can find. Maybe bringing their weapons will spark something.", objectives = "Find the cause of the Valor family ghosts in Raven Hill for Sirra Von'Indi in Darkshire." }
WordHunterWoW_QuestEN[98459] = { title = "A Lack of Virtue", description = "Bart Tidewater's a no-good cheapskate, I tell ya!\n\n\"Captain of the Maiden's Virtue\" he calls himself. That ship's sailed as far as a rock in Tanaris! He's no captain, he's an actor who won enough hands of poker to buy the Virtue in the first place!\n\nIf you ever find yourself in Menethil Harbor over in the Wetlands, give this to him and let him know it's from ol' Half-fish.\n\nThere's a boat from here that can take you right to the harbor, by the way. It'll be the second stop!\n\nAnd he cheats at poker!", objectives = "Deliver Tom's Gift to Bart Tidewater in Menethil Harbor in the Wetlands.", progress = "Put yer backs into it! We set sail on my word!\n\nOh? What's that you have there, traveler?", completion = "<Bart unwraps the gift.>\n\nWhy that no good, son of a--\n\nDid he even tell you that HE is the one who cheats at poker?! I only won enough money to buy the Maiden's Virtue after we kicked him out of our poker circle!\n\nI swear, the next time I see that absolute waste of seawater--\n\nI'm sorry, I'm sorry. I shouldn't shoot the messenger. On behalf of the crew of the Maiden's Virtue--finest ship in the Great Sea--welcome to Menethil Harbor!" }
WordHunterWoW_QuestEN[98461] = { title = "Unrequited Love", description = "If you're heading out of Auberdine, I could use your help!\n\nMy dear friend Tarrel and I were classmates in school. Oh, he was such a quickfire on all things excavation! We got split up after graduation--him to Wetlands, and me to here in Darkshore.\n\n<Hollee sighs, then her brow furrows slightly.>\n\nSorry, and his wife... Merrin.\n\nIt doesn't matter. If you go to the Wetlands, could you make sure he's alright? And maybe give him this? He's probably near Menethil Harbor. There's a boat straight there.", objectives = "Deliver Hollee's Note to Tarrel Rockweaver near Menethil Harbor in the Wetlands.", progress = "What's all this about?", completion = "<Tarrel reads the note.>\n\nOh... oh my. Poor Hollee.\n\nShe always did have a bit of a thing for me. And, truth be told, there was a time where I would have reciprocated. But I'm married. Happily married!\n\nI think the best thing to do here is not to reply. I don't know how to let her down, and I have far more pressing things to worry about here! My wife is missing!" }
WordHunterWoW_QuestEN[98463] = { title = "Talk of the Town", description = "Look, I'm glad to have you at my bar, and that's exactly why I'm telling you this.\n\nThe real party? That's over at the Salty Sailor Tavern in Booty Bay. Yes, in Stranglethorn Vale--that Booty Bay.\n\nDon't give me that look. I know it's run by goblins. Bartenders talk, and bar patrons talk a LOT. All I'm saying is that if you want to see things get real wild, head over there.\n\nNixxrax Fillamug will keep you topped up, don't even worry.", objectives = "Visit Nixxrax Fillamug in the Salty Sailor Tavern in Booty Bay in Stranglethorn." }
WordHunterWoW_QuestEN[98471] = { title = "Message from the Supreme Magister", description = "Greetings, {name}. \n\nI have an assignment for you that is of the utmost priority. Please meet me in the mountains called Alterac, northwest of the village known as Strahnbrad. I will meet you at the cliff overlooking the Uplands valley.\n\nCome alone, and tell no one.", objectives = "Meet Elaadrin Evengale at the cliffs overlooking The Uplands in Alterac Mountains." }
WordHunterWoW_QuestEN[98512] = { title = "Al'Aketh Assassins", description = "You there, stranger. Get low and keep quiet. We are not alone here.\n\nI was on patrol near the border and noticed that there are a number of Al'Aketh skulking around the house just up the hill there to the north. I don't know what they are doing here, but it can't be good.\n\nIf you want to make yourself useful, get in there and take them out. I'll wait here and watch your back.", objectives = "Kill 10 Al'Aketh Assassins in the Shen'dar Highlands.", progress = "I wonder what they are after?", completion = "I'm glad you made it back. That group of Al'Aketh looked like stone cold killers. \n\nThank you for your aid, I'll include your assistance in my report when I return to Valanaar." }
WordHunterWoW_QuestEN[98517] = { title = "Call of Fire", description = "Greetings, young Skyborne. The spirits have spoken of you, and tell me that you are ready to heed the call of fire. However, I shall not be the one to start you on that Path. Return to your home in the elemental plane, seek your mentors there. They will tell you what must be done.", objectives = "Report to Sessaria Skystride or Aarnor Galestrike on Zephras Isle to continue your training as a Shaman. \n\nYou can return to Zephras via the skycutter transport that docks in Mulgore at Skywatcher Plateau, northwest of Thunder Bluff." }
WordHunterWoW_QuestEN[98545] = { title = "Leonid's Letter", description = "Since you are here, I'd like you to deliver this letter to an old friend of mine in the Undercity. I'd deliver myself but I have a somewhat colorful history with the Dark Lady, and it would be better if a neutral third party made the delivery.\n\nYou are looking for a goblin named Glix Xizzix in the Trade Quarter area of the Undercity. I'm sure he'd be happy to compensate you for your time.\n\n<Leonid lets out a low chuckle as he hands you the letter.>", objectives = "Deliver the Sealed Letter to Glix Xizzix in the Undercity.", progress = "What's that? You say that Leonid sent you? Oh boy, haven't seen that crusty old soldier since Naxxramas was raining hell down on our heads.", completion = "Thanks for delivering this, pal.\n\nWait... he said I'd tip you? I didn't agree to that! \n\nFine. Take your pick of this junk in the lost and found. You'd be surprised how many of these Forsaken leave their stuff laying around after getting haircuts. There's a joke here about them being brainless, but I suspect in a lot of cases it might actually be true." }
WordHunterWoW_QuestEN[98574] = { title = "Hallowed Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Hallowed Memorandum and speak to Branstock Khalder in Anvilmar.", progress = "Ah, another {race} comin' ta learn about the Light! You'll find that deepening your connection to the Light relies on curiosity and intelligence, qualities that many gnomes have in abundance. The way o' the Light isn't a technical discipline, it's a riddle, and one that provides both life lessons and practical blessings.", completion = "With time and practice, you'll discover new facets to the Light. In a way, it's finding a union between what you think and what you feel. As you deepen your connection with the Light, you can come back to me to talk about what you've learned. I'll be happy to show you how to tap into that force to teach ya how to heal, or to smite the wicked. For a small donation, of course!" }
WordHunterWoW_QuestEN[98575] = { title = "Tainted Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer, Nartok. He would have words with you when you're ready.", objectives = "Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials.", progress = "Ah, you received my message. Excellent. We orcs have a long and turbulent history with the entities of the Nether, but now we forge our own path, in command of our destiny. You, too, can seize the power to shape the future for your people. Where our leaders falter, we are ready to press forward and claim our rightful place. You will be of eminence among the trolls.", completion = "You have just glimpsed the power that can be yours. The feeble and foolish among us are afraid of the path that we tread, but with boldness and cunning we can decide our own fates.\n\nGuard your powers closely. The fearful lash out against that which they do not understand.\n\nNow you are one of us. If you need training in spells then return to me." }
WordHunterWoW_QuestEN[98576] = { title = "Glyphic Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready.", objectives = "Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", progress = "Ya come to Mai'ah ready to learn. Dat be good. Ya got da power to touch da strands of da cosmos, but ya also got da wisdom to know dat you need guidance. I can teach ya da first steps to wield dat power.", completion = "Da magic dat flows through you be da greatest power in da universe, but ya must be patient. Wait for da perfect moment to strike. Choose da right response to da problem at hand. If you be smart, and you watch carefully, dere be nothing you can't do.\n\nWhen ya tink you be ready for trainin', come back to Mai'ah. She teach you what you ready to learn, no problem." }
WordHunterWoW_QuestEN[98581] = { title = "Archaic Rune", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. Based on the Wildhammer style to these inscriptions, I'm guessin' this came from the shaman trainer Teo Hammerstorm. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Archaic Rune and speak to Teo Hammerstorm in Anvilmar.", progress = "Ah, you were able to read the rune? It is imbued with the power of elements from some of our oldest script. That shows that you have the makings of a {class}.", completion = "The shamanic arts have been kept by the Wildhammer clan for years, an' now those arts have passed into the care of the Bronzebeard dwarves as well. I'm here ta help spread these teachings an' offer guidance for new shamans learning the ways of the elements. Come ta me if ya need more trainin' in the spells of earth, air, fire, an' water." }
WordHunterWoW_QuestEN[98601] = { title = "A Difficult Path", description = "While you were off dealing with the mindless Scourge, this scroll arrived for you. It reeks of the light, so I imagine its of some importance to a paladin like yourself.\n\nRead it before heading out again. Just please--step away when you do. Paladins make me quite uneasy.", objectives = "Read the Consecrated Scroll and speak to Aramis Hammerhand in the church in Deathknell.", progress = "Through pain comes resolve.", completion = "Your training can now begin in earnest, {class}. I see great promise in you, but take care not to turn away from the light, even for a moment. Embrace the pain it will cause you. That pain is a crucible, and you will emerge from it stronger than you ever were in your previous life." }
WordHunterWoW_QuestEN[98731] = { title = "Blessings of the Great Cat Spirit", description = "Now that you have received my blessing, return to Dendrite. He will instruct you further. I do hope we meet again someday.\n\nMay the shadows forever hide you and your foes easily fall prey to your claws, young one.", objectives = "<Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.>\n\nI sense the cunning and ferocity of the cat within you that was not present when I sent you to meet the Great Cat Spirit. In your eyes I can sense you now understand the stealth and speed needed to adopt this nature.\n\nNow you may learn to focus your cunning and adopt the true nature of the cat and call upon its spirit.", completion = "<Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.>\n\nI sense the cunning and ferocity of the cat within you that was not present when I sent you to meet the Great Cat Spirit. In your eyes I can sense you now understand the stealth and speed needed to adopt this nature.\n\nNow you may learn to focus your cunning and adopt the true nature of the cat and call upon its spirit." }
WordHunterWoW_QuestEN[98738] = { title = "Blessings of the Great Windborne Cat Spirit", description = "Now that you have received my blessing, return to Dendrite. He will instruct you further.\n\nUnfortunately I have little left to teach you for the moment. I do hope you come and visit me in Zephras again someday. I sense promise in you, young shen'dorei.\n\nMay the shadows forever hide you, your foes easily fall prey to your claws, and the winds guide your steps.", objectives = "<Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.>\n\nI sense the cunning and ferocity of the cat within you that was not present when I sent you to meet the Great Cat Spirit. In your eyes I can sense you now understand the stealth and speed needed to adopt this nature.\n\nNow you may learn to focus your cunning and adopt the true nature of the cat and call upon its spirit.", completion = "<Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.>\n\nI sense the cunning and ferocity of the cat within you that was not present when I sent you to meet the Great Cat Spirit. In your eyes I can sense you now understand the stealth and speed needed to adopt this nature.\n\nNow you may learn to focus your cunning and adopt the true nature of the cat and call upon its spirit." }
WordHunterWoW_QuestEN[98739] = { title = "Blessings of the Great Cat Spirit", description = "Now that you have received my blessing, return to Dendrite. He will instruct you further. I do hope we meet again someday.\n\nMay the shadows forever hide you and your foes easily fall prey to your claws, young one.", objectives = "Speak to Dendrite.", completion = "<Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.>\n\nI sense the cunning and ferocity of the cat within you that was not present when I sent you to meet the Great Cat Spirit. In your eyes I can sense you now understand the stealth and speed needed to adopt this nature.\n\nNow you may learn to focus your cunning and adopt the true nature of the cat and call upon its spirit." }
WordHunterWoW_QuestEN[98815] = { title = "Highland Hides", description = "The Highlands are host to ruins of some sort, secrets now being explored by an expedition team. What I know is that they've got their own wildlife and beasts lurking in that mountain marshland. How about you take a foray in there with some well-equipped friends, and we work a trade?\n\nI don't care if they're hiding, I want their hides! Bring me the skins from four of the Thicket Raptors, I'll have a trade worked out for you to make it worth it.", objectives = "Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor." }
WordHunterWoW_QuestEN[98823] = { title = "Earthen Echo", description = "Truly, this is a fascinating object.\n\nIt shows indications of being much more than a mere carving or sculpture.\n\nWhile our elders may be interested in observing this artifact, the Earthen Ring are who would carry the most wisdom for our buried ruins and forgotten lands. Seek out Muln Earthfury, a direct approach is fitting for the gravity of what you carry.\n\nYou can find him and other elders of the Earthen Ring council at the Skywatcher Plateau in northwest Mulgore.", objectives = "Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore." }
WordHunterWoW_QuestEN[98824] = { title = "Prehistoric Prism", description = "With titan-like inscriptions like that on its facets, nothing less than Ironforge's Hall of Explorers is the right place to bring it.\n\nI'd like to think that you'll be noted in the history for it in the catalogue -- \"Recovered by {name}! Authenticated by Prospector Whelgar...\" Ah, I'm gettin' meself carried away.\n\nHigh Explorer Magellas will receive you, and given the exquisite nature of what you carry, will surely be most generously appreciative should you donate it to the museum.\n\nGood find!", objectives = "Bring the Titan Relic to High Explorer Magellas in Ironforge's Hall of Explorers.", completion = "What's this you've got...\n\nWoah! Look at this marvel! The light through it dances like nothin' I've seen since my first dig in old Uldaman. The marks of the keepers on this cannot be mistaken.\n\nYou've done the League a great service bringin' this home. A find like this pushes the very boundaries o' the world's wisdom forward.\n\nWe'll be sure to record the details of your contribution! Truly a job well done, adventurer." }
WordHunterWoW_QuestEN[98887] = { title = "Conflict at Darkspear Islands", description = "The Theramore Expeditionary Force are tenacious and continue to send reinforcements to bolster their position on the Darkspear Islands. \n\nGo, show them the might of the Horde! Bring me the evidence of your victory in this key battleground and you will be well rewarded.", objectives = "Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[98888] = { title = "Conflict at Darkspear Islands", description = "The fight in Darkspear Islands is ceaseless, {name}. Together, we will destroy the Alliance dogs in the Theramore Expeditionary Force!", objectives = "" }
WordHunterWoW_QuestEN[98895] = { title = "Darkspear Islands Clash", description = "The battle against the Darkspear Raiders is heating up. Without urgent aid, the Darkspear Islands will be lost to us. \n\nIt is your duty as a proud member of the Alliance to ensure this does not happen. Bring me proof of your contributions on the front lines and you will be revered as a hero of the Alliance!", objectives = "Bring 3 Darkspear Islands Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[98896] = { title = "Darkspear Islands Clash", description = "The fight in the Darkspear Islands continues, {name}. Rally your forces and crush the Darkspear Raiders!", objectives = "" }
WordHunterWoW_QuestEN[98897] = { title = "Darkspear Islands Clash", description = "The battle against the Darkspear Raiders is heating up. Without urgent aid, the Darkspear Islands will be lost to us. \n\nIt is your duty as a proud member of the Alliance to ensure this does not happen. Bring me proof of your contributions on the front lines and you will be revered as a hero of the Alliance!", objectives = "Bring 3 Darkspear Islands Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[98899] = { title = "Darkspear Islands Clash", description = "The battle against the Darkspear Raiders is heating up. Without urgent aid, the Darkspear Islands will be lost to us. \n\nIt is your duty as a proud member of the Alliance to ensure this does not happen. Bring me proof of your contributions on the front lines and you will be revered as a hero of the Alliance!", objectives = "Bring 3 Darkspear Islands Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[98901] = { title = "Darkspear Islands Clash", description = "The battle against the Darkspear Raiders is heating up. Without urgent aid, the Darkspear Islands will be lost to us. \n\nIt is your duty as a proud member of the Alliance to ensure this does not happen. Bring me proof of your contributions on the front lines and you will be revered as a hero of the Alliance!", objectives = "Bring 3 Darkspear Islands Marks of Honor to an Alliance Brigadier General outside the battlegrounds." }
WordHunterWoW_QuestEN[98903] = { title = "The Battle for Darkspear Islands!", description = "Go forth and represent the Theramore Expeditionary Force in battle at Darkspear Islands, {name}! Achieve victory and show these Horde dogs the might of the Alliance!", objectives = "Win a Darkspear Islands battleground and return back to Brelinda McFarry at Northwatch Hold." }
WordHunterWoW_QuestEN[98906] = { title = "The Battle for Darkspear Islands!", description = "The battle at the Darkspear Islands be locked in a stalemate, {class}. Show those Alliance fools who the superior force is. \n\nCarry your head high in service of the Darkspear and claim victory in battle. The Loa will surely be givin' you their blessing, {class}!", objectives = "Win a Darkspear Islands battleground and return back to Nizook Boof at The Merchant Coast." }
WordHunterWoW_QuestEN[98977] = { title = "Mossheart the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[98983] = { title = "Frostleaf the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[99046] = { title = "The Lost Runner", description = "The Council of the Forest sent a small group of sentinels to the Oracle Tree some time ago. The tree sends messages to our elders, and it falls to us to deliver them to Darnassus safely.\n\nI received word that our most recent runner has not yet arrived. The Oracle's messages vary in frequency, but it has been abnormally long.\n\nPlease head towards the Oracle Glade along the road to the west and check on her. It would have been Eralya Leafshadow's turn, and she is still in training. Elune guide you.", objectives = "Search for Sentinel Eralya Leafshadow on the road leading to the Oracle Glade.", completion = "Elune's grace... I shall not die... alone..." }
WordHunterWoW_QuestEN[99047] = { title = "Not Dead Yet", description = "My sisters and I... were dispatched... Oracle Tree...\n\nTree... message. I... harpies... everywhere...\n\n<Eralya coughs up blood, grimacing through the pain.>\n\nI may not have long... no one coming. Please... Byancie... in Dolanaar...", objectives = "Seek aid from Byancie in Dolaanar for Sentinel Eralya Leafshadow.", completion = "The harpies have become afflicted by the same foulness showing up throughout the forest. I'm sure that is what ails Sentinel Eralya as well.\n\nWe must hurry. It won't be long before she succumbs to her injuries." }
WordHunterWoW_QuestEN[99048] = { title = "A Missing Hand", description = "A member of the Shattered Hand, a group of more... subtle fighters, was watching Tiragarde Keep from a distance. Her reports suddenly stopped coming in.\n\nI doubt the humans would have caught her, so I'm concerned something more dangerous is at play. See if you can find her. Hopefully the messages are just delayed.", objectives = "Find Heglan Shadeeye north of Tiragarde Keep.", completion = "Heglan's body lies cold within the wreckage of the hut.\n\nWhatever killed her doesn't seem to be human. There may be signs of what happened nearby." }
WordHunterWoW_QuestEN[99049] = { title = "Threat from Below", description = "The nearby area is destroyed with obvious signs of a skirmish. Whatever ambushed Heglan didn't make it out unscathed. There's probably signs nearby of what happened.\n\nOrgnil will probably want to see any evidence left by the attackers.", objectives = "", completion = "This banner and blade piece belong to the naga! They must have come down the coast from the north.\n\nWe cannot let them establish a foothold here. The pressure from both directions would be too much for Razor Hill." }
WordHunterWoW_QuestEN[99050] = { title = "The Great Tree Provides", description = "I will need your help acquiring the ingredients I need to stop the affliction long enough for Eralya to make it back here for further treatment.\n\nThankfully, our living home is still bountiful and will provide in our time of need.\n\nThe core ingredient is dewy lasher fronds. You'll find them around Lake Al'Ameth directly south of here, or Wellspring Lake and its river to the northwest.\n\nIn addition, I'll need an empty vial and some spring water. Both can be bought here in town, or traded for.", objectives = "", completion = "Thank you for your help. Please, accept this to help with the costs of the vial and water.\n\nNow, to make the salve. It should only take a moment." }
WordHunterWoW_QuestEN[99051] = { title = "Threat from Below", description = "It wouldn't be the first time those snakes bothered us. They need to be taught that their presence is not tolerated here.\n\nFind where their scouts are setting up camp and slaughter them. Bring me back their fins as proof. We need to act fast to make sure they understand.", objectives = "Collect X Naga Spinefins.", completion = "Hopefully that sends them packing back to the north. I'll have some grunts keep an eye out for any stragglers or funny business." }
WordHunterWoW_QuestEN[99052] = { title = "Threat from Below", description = "One of my scouts has reported a sea giant followed those naga down here. Not sure if they brought him intentionally or what, but he's dangerous in any case.\n\nIt's a young one, but it could still rip an orc in half in a heartbeat if they were caught off guard. I need him gone. But I'd suggest you find some help to deal with it.", objectives = "", completion = "Ha! I could hear his body fall from here!\n\nBe proud of your kill today, not many can claim they survived a fight with a sea giant." }
WordHunterWoW_QuestEN[99053] = { title = "Escaping Ban'ethil", description = "My prayers have been answered! I am thankful that you have fought your way down here.\n\nI was sent here by the Oracle Tree to deliver a message to the slumbering druids here only to find it completely overrun by furbolg! They ambushed me before I could turn back and brought me down here--I fear for their next meal.\n\nI don't know about you, but I loathe this place. Under the earth is no place for the kaldorei.", objectives = "", completion = "Thank Elune you were around to help Lynessa avoid a dark fate with the Gnarlpine. She's one of our best, and a personal friend.\n\nPlease, take this in thanks. May it serve you well in keeping the kaldorei safe." }
WordHunterWoW_QuestEN[99073] = { title = "Easing Suffering", description = "The salve is ready. Take it to Eralya swiftly.\n\nI do not know if it will truly cure her. The rot festers quickly, and grows in strength as it spreads.\n\nIt will, if nothing else, ease her suffering. And that is still worth your haste.", objectives = "", completion = "<Eralya's breath calms quickly as you help her ingest the salve. She may not survive, but is at relative peace.>" }
WordHunterWoW_QuestEN[99079] = { title = "Longwalker Malah", description = "The Longwalkers are our people's most trusted scouts. Though their loyalty lies with the High Chieftain alone, young Baine at times seeks their aid.\n\nThis is one such time. Longwalker Malah was dispatched near our borders to the east and did not return last night after three days. When this occurs, it is our duty to confirm their safety.\n\nI must ensure the village remains safe. Prove yourself, and seek Malah out. You will know her by her headband and feathered staff, emblematic of the Longwalkers.", objectives = "Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore.", completion = "It is clear that Malah did not die naturally. Arrows cover her back and the ground nearby." }
WordHunterWoW_QuestEN[99080] = { title = "Drive Them Out", description = "Hear my words well: we will not yield a single blade of grass to the centaur.\n\nGo to their camp now, before they have rested and have a chance to ride to our village. Slaughter them all. Ensure none escape to the Barrens to rally others to their aid.\n\nIf you find the leader of this would-be raiding party, bring me his head so that it may serve as a warning to others who dare tread on our ancestral homeland.", objectives = "Kill X Galak Centaurs, X Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof.", completion = "You are covered in centaur blood. Remember this feeling. It is an honor unlike any other among our people.\n\nI could hear the moment the last fell, and their thunderous stampede echoed no longer. Well done!\n\nToday marks a great victory for our village, and a security our young ones need now more than ever. You have my deepest thanks, young {class}." }
WordHunterWoW_QuestEN[99081] = { title = "Grim Tidings", description = "You can see what appears to be a new centaur camp in the direction the arrows in Malah's back would have come from. There is a stir of activity, suggesting a small raiding party has made its way into Mulgore.\n\nThe Longwalker has a report in her still-clenched hand. Brave Wildrunner will want to know of Malah's fate--and her killers.", objectives = "Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village.", completion = "This is most dire news indeed. We must inform Baine at once!" }
WordHunterWoW_QuestEN[99082] = { title = "The High Chieftain", description = "Your bravery defending your people demands recognition. Journey to Thunder Bluff to the northwest, our mighty city whose shadow grants us shade in the warmer months, and seek audience with my father.\n\nIt was he who led the charge with the young Warchief Thrall to reclaim these plains and drive the centaur away for good. As High Chieftain, he will reward you generously for your part in ensuring his own bravery is honored.\n\nYou must take a lift to reach the High Chieftain, who sits on the central rise.", objectives = "Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff.", completion = "The Galak centaur dare show themselves in Mulgore?!\n\nYou have brought pride to your ancestors by driving them out. Perhaps that will remind them of the pain that awaits them should they do so again!\n\nPlease accept this gift in honor of this. May it serve you well as you venture out into the Earth Mother's kingdom, to the far reaches of this world." }
WordHunterWoW_QuestEN[99101] = { title = "Our Ancient Enemy", description = "Baine Bloodhoof leads our village. He must know of this incursion at once.\n\nBring him Longwalker Malah's report. You will find him at the center of town.\n\nQuickly, now. There is no time to waste!", objectives = "Bring Longwalker Malah's Report to Baine Bloodhoof.", completion = "<Baine reads the report, his gaze darkening.>\n\nThis will not stand. Thank you for delivering it to me, Vanyel." }
WordHunterWoW_QuestEN[99108] = { title = "Sparring Match", description = "Hail, young {class}. Though you are not a warrior and I cannot teach you that path, that does not mean you would not benefit from my tutelage.\n\nBefore you lies the arena. In it, it matters not who you call mother or whether you wield sword or bow. All are equal, and all learn to sharpen their horns in direct combat.\n\nWill you enter our space, and learn our ways for yourself? You may face any of these novices, or any other willing adversary. I care not which.", objectives = "Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof.", completion = "You honor me with your abilities, {class}. Perhaps the new generation has hope yet.\n\nTake these to tend to your wounds, for many more battles await you in this harsh world." }
WordHunterWoW_QuestEN[99123] = { title = "Lost in the Shadows", description = "I decided to do a bit of scouting in the crag on my own. Unfortunately my magic ran out at the wrong time and I've been stuck hiding here since.\n\nIf you could help me escape, I would appreciate it.", objectives = "", completion = "Ah, Pal'juh got herself in trouble again, did she?\n\nHopefully she learns her lesson about going alone this time. Thank you for helping her. She's a promising hunter, just tends to act more like a raptor than a tiger." }
WordHunterWoW_QuestEN[99127] = { title = "A Net Disaster", description = "The fish just ain't biting today, and there's something wrong going on with them. It's not just empty hooks. I haven't seen a single minnow up in the water at all.\n\nLee here set up some traps overnight, go check to see if we've at least got some stock there. If you find anything weird, make sure to show me.", objectives = "", completion = "All the traps are like this? Seems our new neighboring nuisances are causing more destruction than we were aware of. I'll go broke if we don't do something about it." }
WordHunterWoW_QuestEN[99128] = { title = "Slimy Menace", description = "This can only be the work of those murlocs on the other side of the lake. They're disgusting little things, with a vicious temper and teeth to match.\n\nIf we let this continue, there won't be any fish to speak of anywhere in this lake. If you could clear them out a bit, it would help me a ton.", objectives = "", completion = "I can hear their warbling from here, it'll be in my nightmares. Well, that should slow them down--although I have no doubt that they'll make up those numbers quickly." }
WordHunterWoW_QuestEN[99129] = { title = "A Man About a Murloc", description = "Remy mentioned murlocs the other day... I'm pretty sure he hates the little buggers as much as I do.\n\nHe might have some ideas on how to keep them away from my fish in the future. I'd like to ask you to go chat with him and see if there's anything he can think of.", objectives = "", completion = "I've been warning the guards about the murlocs. They won't listen.\n\nI have a few ideas on how to get back at those critters. I'll need your help getting what I need for it though." }
WordHunterWoW_QuestEN[99130] = { title = "An Enticing Offer", description = "I've got a few ideas on how to deal with murlocs. And one of those also helps some others in the process.\n\nThere's a weed often found on farms in the area called duskweed, and in large quantities the petals are toxic to most animals. If we make some murloc bait with the plant, hopefully that can train those creatures to stay away.\n\nAnd some farmers get their fields cleared in the process. Truly a win-win... truly a win-win.", objectives = "", completion = "Give me just a minute...\n\nIt's pretty simple bait, but as long as nobody's pet gets into it, it should be safe. Just tell Jason not to eat any of it." }
WordHunterWoW_QuestEN[99131] = { title = "Baited for Success", description = "Tell Mathers he can come pick up the bait later today. I'll give him the rundown on the proper usage.\n\nHopefully he'll be able to sell his fish again soon. And we'll have less murlocs in this world.", objectives = "", completion = "Poisoned bait? As long as the fish aren't going to eat it, that should work. I'll visit Remy later to pick it up." }
WordHunterWoW_QuestEN[99134] = { title = "Discipline", description = "You are not a member of the Deathguard, and therefore have yet to disappoint me.\n\nAs a reward for your lack of incompetence, you shall be rewarded with punishing those that have demonstrated such talents in excess.\n\nSwiftly now--{name}, is it?--or I shall add your name to my ledger for someone else's reward.", objectives = "", completion = "There are precious few delights afforded to us in death. Thankfully, pain is chief among them.\n\nYou please me this day, and therefore you please the Dark Lady. Perhaps you can be of further use." }
WordHunterWoW_QuestEN[99141] = { title = "Patience", description = "Make no mistake, {class}--the Dark Lady demands the perfect execution of her will. As an Executor, it is my duty to see that this happens.\n\nReports from several of my Deathguards are overdue. Needless to say, my patience has run out. Obtain their reports and bring them to me in the Dark Lady's name.\n\nYou will find Deathguard Dillinger just west of here, by the graveyard. Deathguard Kristof is stationed at the waystation to the east. And check on the abomination Gordo; he wanders west near Stillwater Pond.", objectives = "", completion = "I should have known better than to think an abomination could write anything of use. Let us keep that lapse of judgment between us.\n\nYou have pleased me, and therefore pleased the Dark Lady. Perhaps there is hope for you." }
WordHunterWoW_QuestEN[99142] = { title = "Tomb Weed", description = "If you're heading east, towards the Balnir Farmstead, I have more you might do for me. Good help is ever so hard to find these days, as your run-in with Gordo illuminates ever so clearly.\n\nAs I acquire doom weed I perform some minor alchemical alterations and replant them on that farmstead to cultivate my ultimate creation. I call it tomb weed, and it shall be the herald of my glorious destiny.\n\nDo keep an eye on the Scourge in the area while you're there. They seem... drawn... to the weed. Curious.", objectives = "", completion = "Most glorious indeed!\n\n<Junior Apothecary Holland inspects the weeds.>\n\nHmm, I had hoped they would have matured a bit more violently. Nevertheless, progress is progress!\n\nA great many will die as a result of your actions this day. You should be proud." }
WordHunterWoW_QuestEN[99143] = { title = "Bottles and Baubles", description = "Those fish men must think like actual fish, right? Which means anything they like, fish will like!\n\nIf you rummage through some of their junk and return to me with anything that seems like it would make good bait, I'll reward you.", objectives = "", completion = "An interesting collection. These should work well enough!\n\nHere's some of my own older supplies. It should help anyone trying to get their footing in fishing." }
WordHunterWoW_QuestEN[99144] = { title = "Seeking Refuge", description = "Light bless you for finding me. I was on my way from Bandarion Keep to deliver a message to Shari Stilwell in Brill when these monsters captured me. They wield the Light with a hatred in their hearts that makes what's left of my blood seethe. It goes against all we stand for!\n\n<Bareth Dawnstone steadies himself.>\n\nOur ranks are thin. If you would aid me in escaping this place, I would be forever grateful.", objectives = "", completion = "Blessings upon you for aiding Dawnstone. Our order is still taking root here and it would be devastating to lose one so promising before his time.\n\nPlease accept this as a token of our thanks. Should you ever take an interest in our ways, our monastery Bandarion Keep lies on the bluffs northwest of the Solliden Farmstead. We welcome all who seek guidance in the Light." }
WordHunterWoW_QuestEN[99152] = { title = "As Above, So Below", description = "While the Tarnished in Shadowvale to the southwest are definitely a problem, we cannot allow the cellars below the town to fester into a full-blown Scourge uprising on Bandarion Keep.\n\nI need to get these trainees up to snuff in case that happens. You, however, are going to receive what I like to call a crash course.\n\nTravel beneath Shadowvale and retrieve some of their wretched bones so we can study them further. I need ones that still retain some of the initial reanimation magic--that's glowing ones.", objectives = "", completion = "Well done, recruit. We might just make something out of you yet.\n\nWith these bones we may be able to better understand how such a threat was able to go unnoticed for so long." }
WordHunterWoW_QuestEN[99153] = { title = "The One That Got Away", description = "Oi, you! Word travels quickly among our ranks. I heard about the work you did with the cultists around the remnants of the battle with Naxxramas.\n\nProblem is, one of them cultists got away with a piece of the focusing crystal. Seems to still have some juice in it. Best guess we have is it's somewhere beneath Shadowvale. It's either raising 'em or making 'em stronger, and you don't want either one.\n\nFind that crystal before this gets out of hand.", objectives = "", completion = "Well done--and quick, too! Now onto my favorite part..." }
WordHunterWoW_QuestEN[99156] = { title = "Rear Guard Patrol", description = "Damn it all! A new report came in while you were on patrol. There has been a sighting of a rogue abomination wandering Eastern Tirisfal Glades, near Venomweb Vale.\n\nSomething is wrong. Abominations don't just slip through the Bulwark unnoticed.\n\nKeep this matter on a strictly need-to-know basis. That said, such a creature will not fall easily; you will need allies if you wish to be more than its next meal.\n\nSee this through, and you will be duly rewarded. Bring me its heart as proof of the deed.", objectives = "", completion = "You are a testament to the cunning and coordination that all Forsaken possess--something the mindless Scourge will never have.\n\nPlease accept this as thanks for your efforts, as promised." }
WordHunterWoW_QuestEN[99158] = { title = "Dawn in the Mountains", description = "There's a priest out in the mountains that belongs to an organization called the Argent Dawn. They're a holy group that is dedicated to finding and destroying the unholy and unnatural.\n\nFather Gavin though, he's mostly the type that seeks to help and heal everyone rather than grab a weapon. He's fixed up an old building to serve as a rest spot for travelers and called it Misty Pine Refuge. I've got a shipment of holy candles that I need to get him. Could you bring them to him if you're going that way?", objectives = "Bring the crate of candles to Father Gavin at Misty Pine Refuge.", completion = "Ah. Candles from Ironforge.\n\nWhile I am mostly able to live independently in my hermitage, there are a few key things that I appreciate from the city and the pious." }
WordHunterWoW_QuestEN[99159] = { title = "Finding Warmth", description = "My hearth is open to warm any soul, but I'd like to ask you to help me if you could.\n\nI simply need more firewood. It is something I would normally do myself, but I have been preoccupied by other tasks.", objectives = "Collect X pieces of firewood.", completion = "Ah, perfect. These will do--any that are too wet to use right now I will leave to dry.\n\nNow, if you're willing, I have more tasks I could use help with." }
WordHunterWoW_QuestEN[99160] = { title = "Rime's Wrath", description = "You may have noticed the elementals nearby. A shelf of rock and ice fell from the mountain peaks a few days ago and riled them up.\n\nThese frozen mountains are already treacherous for the average dwarf or human without the elements taking form. I am not one for fighting anymore--so any of the spirits you can kill would help make the road safer.", objectives = "Destroy X minor ice elementals.", completion = "I wish we could have simply placated them. Unfortunately it was beyond my knowledge and they were too dangerous to leave unchecked." }
WordHunterWoW_QuestEN[99161] = { title = "Rime's Wrath", description = "I noticed that the first elemental that appeared after the rockslide was larger than its peers. And from what I can tell, it has been the source of occasional weather changes and other minor slides.\n\nI've been calling it 'Avala', if you could kill it and retrieve the core as proof, I will reward you.", objectives = "Kill Avala and retrieve its core.", completion = "Light bless you, {class}. Your efforts make this area much safer and hopefully will prevent unnecessary deaths." }
WordHunterWoW_QuestEN[99162] = { title = "Treacherous Cold", description = "Even mountaineers from Ironforge have to keep their wits about them when traversing through the peaks of Dun Morogh. Falling snow and ice often spells the end of some more novice members' lives.\n\nAfter a slide, I usually try to find any sign of survivors or victims--while praying to the Light that there's nothing to be found. But with the elements acting up, I've held off wandering too far. If you could look for some lost mountaineers and bring me their rifles, I will return them to Ironforge.", objectives = "Collect the rifles of fallen mountaineers.", completion = "The mountaineers engrave their names on the stock of their rifles. It helps identify them should something happen. I'll send these back to Ironforge--there someone will pass them on to any family." }
WordHunterWoW_QuestEN[99191] = { title = "A Donation of Wool", description = "The High Order are currently accepting donations for wool cloth.\n\nA donation of sixty pieces of wool cloth will net you full recognition by the High Order for your generous actions.  Sixty pieces of wool should prove to be a sufficient amount for the High Order's needs for now.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", objectives = "" }
WordHunterWoW_QuestEN[99196] = { title = "A Donation of Wool", description = "The Windshapers are currently accepting donations for wool cloth.\n\nA donation of sixty pieces of wool cloth will net you full recognition by the Windshapers for your generosity.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", objectives = "" }
WordHunterWoW_QuestEN[99197] = { title = "A Donation of Silk", description = "", objectives = "" }
WordHunterWoW_QuestEN[99260] = { title = "Fillion's Mission", description = "I was tasked to retrieve important data on the flow of elemental energy from the Overlook Standing Stones. That data is vital to our plans to safely travel between Skywall and Azeroth. Without that data to aid in our calculations, our attempts to steer our skycutter ships through the elemental plane will fail.\n\nThe data is likely lost at this point, and I'm in no state to attempt to gather it again. I told the Supreme Magister of your role in saving me, and he wishes to speak with you again.", objectives = "", completion = "Thank you for saving Fillion, {name}. I'm sure he told you how vital the data he was sent to retrieve is.\n\nWithout that data, our prospects for opening safe lanes of travel to Azeroth is at serious jeopardy. Our spies tell us that the Windshapers have themselves procured the means to traverse the planes, and no doubt wish to jealously guard this secret.\n\nAs ever, their own dogmatic hubris take precedence over the good of our people. They are little better than the Al'Aketh." }
WordHunterWoW_QuestEN[99411] = { title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", objectives = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", completion = "Fantastic work, {name}! Kyle came home as soon as he ate and went straight to bed. Thank you for your help." }
